-- UK admission requirements for Ghanaian applicants, copied from each school's own website (checked 13 Nov 2026).
-- Anything a page did not state is left out. Needs step181 (columns admission_info, admission_link, admission_checked).
update schools set admission_info = $q${"ug": "Abertay country page for Ghana lists WASSCE accepted with C6 or above in English (English page). Course pages state grades and subjects. Ghana page itself not read.", "english": "IELTS 6.0 overall, no part below 5.5 (some courses 6.5 or 7.0). Duolingo 105, PTE 59, TOEFL iBT new scale 4. WASSCE C6 or above in English accepted with WAEC scratchcard.", "ghana_page_link": "https://www.abertay.ac.uk/international/africa/ghana/", "sources": ["https://www.abertay.ac.uk/international/find-your-country/", "https://www.abertay.ac.uk/international/english-language-requirements/"]}$q$::jsonb, admission_link = $q$https://www.abertay.ac.uk/international/africa/ghana/$q$, admission_checked = '2026-11-13' where id = 'f99739d9-e73d-4eba-8466-e197efb2b416' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Year 1: recognised foundation programme, IB Diploma, A Levels, WASSCE/SSCE with C6 or better in English and Maths plus 2 year OND at Lower Credit, or WASSCE/SSCE five subjects at A1/B2/B3 including Maths and English at C. ARU College offers foundation courses.", "pg": "Taught Masters: UK equivalent bachelor degree, minimum lower second (2:2), or Postgraduate Diploma at Upper Credit, or a recognised pre-Masters. Research: overseas qualification equal to a UK Masters.", "english": "Undergraduate IELTS 6.0, no element below 5.5, or equivalent. Postgraduate taught and research IELTS 6.5, no element below 5.5.", "how_to_apply": "Page links to general How to apply pages but gives no Ghana steps.", "fees_link": "https://www.aru.ac.uk/international/fees-and-scholarships", "ghana_page_link": "https://www.aru.ac.uk/international/information-by-world-region/africa", "sources": ["https://www.aru.ac.uk/international/information-by-world-region/africa"]}$q$::jsonb, admission_link = $q$https://www.aru.ac.uk/international/information-by-world-region/africa$q$, admission_checked = '2026-11-13' where id = 'e6e62e9e-2254-40f0-816f-333727cdf6c5' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana not listed. Standard offers 104 to 120 UCAS Tariff points, normally with a creative subject at Level 3. Applicants whose country is not listed should contact admissions@aub.ac.uk.", "english": "Bachelor: IELTS 6.0 (5.5 each band), TOEFL iBT 80, PTE 64. Foundation Diploma IELTS 5.0. Masters from Sept 2027 same as bachelor level. PhD IELTS 7.0. Page does not name WASSCE or Ghana.", "how_to_apply": "Overseas applicants can apply through UCAS, directly (apply.aub.ac.uk), via an agent, or Common App. Postgraduate route is on the postgraduate page, not read.", "deadlines": "UCAS equal consideration deadline 13 January 2027 for September 2027 entry. Portfolio due within about 30 days of request.", "documents": "Personal statement, reference, portfolio or audition where required, transcript for Year 2 or 3 entry, under 18 consent form.", "sources": ["https://aub.ac.uk/apply/undergraduate", "https://aub.ac.uk/international/english-language/english-language-requirements"]}$q$::jsonb, admission_link = $q$https://aub.ac.uk/apply/undergraduate$q$, admission_checked = '2026-11-13' where id = '5d9e6649-6ab9-4096-95f0-591649f2c6fc' and country ilike 'United Kingdom';
update schools set admission_info = $q${"english": "2025/26 entry. Undergraduate IELTS 6.0 (5.5 each part), PTE UKVI 50, LanguageCert 70. Postgraduate IELTS 6.5 (6.0 each part). Pre-degree IELTS 5.5. West African Examination Certificate English Language C4 accepted. Foundation courses 60% accepted.", "how_to_apply": "Apply via aup.ac.uk/apply. Student Route visa needed for international students.", "deadlines": "Pre-sessional English applications: 27 March 2026 (10 weeks) and 1 May 2026 (5 weeks).", "sources": ["https://www.aup.ac.uk/international/language-requirements"]}$q$::jsonb, admission_link = $q$https://www.aup.ac.uk/international/language-requirements$q$, admission_checked = '2026-11-13' where id = 'dd89831a-8897-4848-b322-ba8ac5c41429' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "SSCE holders must first do the International Foundation Programme: average of eight subjects at C6 or above including relevant subjects and C6 in English. Streams: Business, Social Sciences, Engineering, Science. Year not stated.", "pg": "Masters: a Ghanaian university degree with a high percentage or GPA, related background for finance, engineering, science. MBA needs 3 years managerial work. PhD needs a research proposal.", "english": "WAEC English C6 or higher accepted for most taught degrees (C4 for MBChB). No IELTS scores given on the Ghana page. Foundation applicants may use IELTS or TOEFL.", "how_to_apply": "Page links to apply pages and Africa regional manager contact. No steps given.", "documents": "PhD: detailed research proposal. No other list given.", "ghana_page_link": "https://www.aston.ac.uk/international/aston-in-your-country/africa/ghana", "sources": ["https://www.aston.ac.uk/international/aston-in-your-country/africa/ghana", "https://www.aston.ac.uk/international/ghana"]}$q$::jsonb, admission_link = $q$https://www.aston.ac.uk/international/aston-in-your-country/africa/ghana$q$, admission_checked = '2026-11-13' where id = '10c2ca8c-162f-4a4a-8ebf-68beee83feca' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Good WASSCE grade plus 1 year Foundation, or ND, Post-Secondary Certificate or medical diploma. HND holders may enter Year 2. International Year Zero: WAEC/SSC grades A to E in five subjects. International Year 1: good WASSCE plus a year extra study.", "pg": "Taught Masters: Second Class Lower Division bachelor degree. PhD: good bachelor and Masters grades plus research experience. International Incorporated Masters with pre-masters year if requirements not met.", "english": "IELTS 6.0 (5.5) for undergraduate, taught and PhD. IELTS 5.5 for Year Zero and Year 1. Waiver possible with proof of English schooling, such as C in high school English.", "how_to_apply": "Undergraduate: online application portal or UCAS. Postgraduate and PhD: online portal. Page also advises using an agent in Ghana.", "deadlines": "Postgraduate taught: apply by end of June (Sept), end of October (Jan), end of February (May). PhD any time.", "application_fee": "Not stated", "documents": "PhD: degree certificate and transcripts, reference, passport, research proposal, CV. Other levels not listed.", "fees_link": "https://www.bangor.ac.uk/international/tuition", "ghana_page_link": "https://www.bangor.ac.uk/international/countries/ghana", "sources": ["https://www.bangor.ac.uk/international/countries/ghana", "https://www.bangor.ac.uk/international/applying"]}$q$::jsonb, admission_link = $q$https://www.bangor.ac.uk/international/countries/ghana$q$, admission_checked = '2026-11-13' where id = 'e0928483-71a7-4a37-bb05-da8b2c3b3e72' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSCE/SSCE plus a recognised foundation year passed with 60% or above, or plus the first year of a recognised university degree. HND holders may enter Year 2 or 3. Year not stated.", "pg": "Honours bachelor degree with a good passing grade from a recognised Ghanaian institution. No classification defined.", "english": "Ghana page gives no scores. Applicants must meet the university English requirements, qualifications gained within two years of start.", "how_to_apply": "Undergraduate via UCAS or direct from course page. Postgraduate via Apply Now on course page. Research degrees via the Graduate College.", "documents": "Portfolio or interview for some art, music and performing arts courses. Under 18s need UK guardian details.", "fees_link": "https://www.bathspa.ac.uk/students/student-finance/", "ghana_page_link": "https://www.bathspa.ac.uk/students/international/country-advice/ghana/", "sources": ["https://www.bathspa.ac.uk/students/international/country-advice/ghana/", "https://www.bathspa.ac.uk/how-to-apply/international/"]}$q$::jsonb, admission_link = $q$https://www.bathspa.ac.uk/students/international/country-advice/ghana/$q$, admission_checked = '2026-11-13' where id = 'f50d2f6b-5ee4-482b-9c0d-1f1f9ea60cb1' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSC holders can apply for a four year course with a foundation year. Also diploma or HND with GPA 3.0/4.0, or one year of a public university bachelor with GPA 3.0, or A levels or IB (28 to 33). OnCampus London foundation accepted.", "pg": "Bachelor from an accredited university: 2:1 programmes need about 60%, 2:2 programmes 50%. Ghana classes 1st, 2:1, 2:2 listed. Lower degrees considered with work experience. PhD usually needs a 2 year Masters.", "english": "Scores are on course pages, not the Ghana page. WAEC is not an accepted English test.", "how_to_apply": "Undergraduate through UCAS. Postgraduate and distance learning apply direct. PhD: find a supervisor first. Agents must use the StudyLink portal.", "deadlines": "January 2027 intake: standard route application 9 November 2026, final CAS 14 December 2026. Credibility interview route application 26 October 2026.", "documents": "Qualification details, English evidence, financial documents and credibility interview for some visa applicants.", "ghana_page_link": "https://www.bbk.ac.uk/international/country-information/ghana", "sources": ["https://www.bbk.ac.uk/international/country-information/ghana", "https://www.bbk.ac.uk/international/entry-requirements"]}$q$::jsonb, admission_link = $q$https://www.bbk.ac.uk/international/country-information/ghana$q$, admission_checked = '2026-11-13' where id = '9b3f2d36-2f11-45cc-bc7f-4a91495200ef' and country ilike 'United Kingdom';
update schools set admission_info = $q${"how_to_apply": "Apply direct via Apply online on the course page, through an official BCU representative, or through UCAS for undergraduate. Ghana page lists requirement headings but no content.", "deadlines": "Not stated; page advises applying as early as possible.", "fees_link": "https://www.bcu.ac.uk/international/fees-costs-and-scholarships/international-fees", "ghana_page_link": "https://www.bcu.ac.uk/international/bcu-in-your-country/ghana", "sources": ["https://www.bcu.ac.uk/international/bcu-in-your-country/ghana"]}$q$::jsonb, admission_link = $q$https://www.bcu.ac.uk/international/bcu-in-your-country/ghana$q$, admission_checked = '2026-11-13' where id = '019e9a45-1c64-47f3-b9cb-3ecd680c0b6e' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Undergraduate: West African Higher School Certificate or GCE A Level with 13 years of schooling. Foundation Certificate: 12 years of schooling and a Senior Secondary School Certificate. Year not stated.", "pg": "Taught Masters: a bachelor degree from a state or private university accredited by the National Accreditation Board. No classification given. Research: any postgraduate degree.", "english": "Foundation Certificate: IELTS Academic 5.0 or SSSCE English grade 1 to 6. Undergraduate scores are on the separate English requirements page.", "how_to_apply": "An admissions tutor reviews the application with academic background and personal information. No steps given.", "ghana_page_link": "https://www.bournemouth.ac.uk/study/international/bu-your-country/ghana/entry-requirements-ghanaian-students", "sources": ["https://www.bournemouth.ac.uk/study/international/bu-your-country/ghana/entry-requirements-ghanaian-students"]}$q$::jsonb, admission_link = $q$https://www.bournemouth.ac.uk/study/international/bu-your-country/ghana/entry-requirements-ghanaian-students$q$, admission_checked = '2026-11-13' where id = '18e6fd83-1046-40af-8359-010b114e89bc' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "International entry criteria are in a dropdown on each course page; no Ghana list on the pages read.", "english": "Each course page lists its English requirement. For some countries an academic qualification can replace a test; a country selector shows which.", "how_to_apply": "Undergraduate and postgraduate apply via course pages (international applicant pages).", "deadlines": "Admissions policy: UCAS January deadline 14 January for 2026 entry, final UCAS date 30 June. Postgraduate first come first served.", "application_fee": "Not stated. A 5,000 GBP tuition deposit is needed before a CAS.", "documents": "Full official transcript and certificate, copy of passport photo page, copies of any past UK visas.", "sources": ["https://www.brunel.ac.uk/international/applicants/how-to-apply-international-students/requirements-for-international-students-at-Brunel", "https://www.brunel.ac.uk/study/admissions/documents/pdf/Admissions-Policy-and-Procedure-October-2025.pdf"]}$q$::jsonb, admission_link = $q$https://www.brunel.ac.uk/international/applicants/how-to-apply-international-students/requirements-for-international-students-at-Brunel$q$, admission_checked = '2026-11-13' where id = '929be3d6-a532-428d-8ae9-73f6e825fc63' and country ilike 'United Kingdom';
update schools set admission_info = $q${"how_to_apply": "International page states the university is currently only accepting applications from people who do not need a visa to study in the UK. Visa applicants should email international.ask@bnu.ac.uk. Ghana page content could not be read.", "ghana_page_link": "https://bucks.ac.uk/applying-to-bucks/international/your-country/ghana", "sources": ["https://www.bucks.ac.uk/study/international"]}$q$::jsonb, admission_link = $q$https://bucks.ac.uk/applying-to-bucks/international/your-country/ghana$q$, admission_checked = '2026-11-13' where id = 'ac3aaad3-4944-4672-91c7-43e843c63756' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ghana_page_link": "https://www.canterbury.ac.uk/study-here/international/find-your-country/ghana", "sources": ["https://www.canterbury.ac.uk/study-here/international/find-your-country/ghana", "https://www.canterbury.ac.uk/study-here/international/english-language-requirements"]}$q$::jsonb, admission_link = $q$https://www.canterbury.ac.uk/study-here/international/find-your-country/ghana$q$, admission_checked = '2026-11-13' where id = '2f8ad330-6dc8-4e7e-a167-c4a0419a4df2' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Year 0 or 4 year degree: West African Senior School Certificate or SSCE with A1 to C6 or A to D passes including Maths and English. Year 1: good WASSCE/SSCE plus a recognised Foundation course, or WAHSC A1 to B3, or Diploma, HND or Certificate.", "pg": "At least a 2.2 bachelor degree from a recognised Ghanaian institution, or a 1 or 2 year Masters or Postgraduate Diploma.", "how_to_apply": "Page links to How to Apply pages; steps not on Ghana page.", "ghana_page_link": "https://www.cardiffmet.ac.uk/international-students/country-specific-entry-requirements/", "sources": ["https://www.cardiffmet.ac.uk/international-students/country-specific-entry-requirements/"]}$q$::jsonb, admission_link = $q$https://www.cardiffmet.ac.uk/international-students/country-specific-entry-requirements/$q$, admission_checked = '2026-11-13' where id = '08e682ed-8f53-48d5-98af-c0d0bfc7a7ca' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WAEC/WASSCE plus a completed one year International Foundation Programme. Alternatively good A level or IB grades, or one or more years at a recognised Ghanaian university. Year not stated.", "pg": "Taught: a related bachelor degree at a high level, usually Upper Second or higher. Research: recognised Ghanaian Masters, or a bachelor at Second Class Higher Division with possible extra Cardiff Masters.", "english": "For most programmes WAEC or IGCSE results at the right grade can replace IELTS. Foundation applicants must sit IELTS for the study visa. Scores are on another page.", "ghana_page_link": "https://www.cardiff.ac.uk/study/international/your-country/africa/ghana/entry-requirements", "sources": ["https://www.cardiff.ac.uk/study/international/your-country/africa/ghana/entry-requirements"]}$q$::jsonb, admission_link = $q$https://www.cardiff.ac.uk/study/international/your-country/africa/ghana/entry-requirements$q$, admission_checked = '2026-11-13' where id = '92dcb85b-bbe8-4622-8f04-401d314c0aa8' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "General minimum: passes in two subjects at GCE A level or equivalent. City offers foundation programmes for international students via partner providers. Ghana section not read.", "how_to_apply": "Undergraduate via UCAS per City St George's pages. Ghana detail not read.", "sources": ["https://www.citystgeorges.ac.uk/prospective-students/apply/entry-requirements"]}$q$::jsonb, admission_link = $q$https://www.citystgeorges.ac.uk/prospective-students/apply/entry-requirements$q$, admission_checked = '2026-11-13' where id = 'f38630ab-9064-4e5b-afe7-3ef9c993db2c' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Five WASSCE/SSCE subjects at A to B including Maths, English at minimum C; or Federal University diploma at lower credit, or OND. Top-up: HND at upper credit or university diploma.", "pg": "Bachelor degree or Postgraduate Diploma at 2:2 or higher.", "english": "UG: IELTS 6.0 (5.5 each), TOEFL iBT 79. PG: IELTS 6.5 (5.5 each), TOEFL iBT 88. WASSCE English at C minimum also listed.", "how_to_apply": "Page links to the international apply guidance.", "fees_link": "https://www.coventry.ac.uk/international-students-hub/fees-and-funding/", "ghana_page_link": "https://www.coventry.ac.uk/international-students-hub/entry-requirements/", "sources": ["https://www.coventry.ac.uk/international-students-hub/entry-requirements/"]}$q$::jsonb, admission_link = $q$https://www.coventry.ac.uk/international-students-hub/entry-requirements/$q$, admission_checked = '2026-11-13' where id = '51d90971-32d3-45e8-b3ce-ec0d46255835' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSC/WAEC with C6 or above plus one of A levels, IB, a Foundation course or a National diploma, for bachelor entry.", "pg": "Degree from a recognised Ghanaian university with 55%, or GPA 2.5/5.0, or equivalent. Some courses need a portfolio, work experience or a related degree.", "english": "Undergraduate IELTS 6.0 (Art, Business, Computing, Engineering), 6.5 Law, 6.5 to 7.5 Science. Postgraduate 6.0 to 6.5 by subject. WASSC/WAEC C6 or above accepted instead of IELTS.", "how_to_apply": "Page links to the DMU international applications guide.", "documents": "IELTS or equivalent if English is not first language. Year 2 or 3 entry needs course details, grades, syllabus and grading guide.", "fees_link": "https://www.dmu.ac.uk/Study/fees-funding/international-tuition-fees.aspx", "ghana_page_link": "https://www.dmu.ac.uk/international/en/entry-requirements.aspx", "sources": ["https://www.dmu.ac.uk/international/en/entry-requirements.aspx"]}$q$::jsonb, admission_link = $q$https://www.dmu.ac.uk/international/en/entry-requirements.aspx$q$, admission_checked = '2026-11-13' where id = 'cf14321d-6c4b-478e-9b43-f3f2d33c5a97' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSC or SSCE plus a recognised International Foundation Year. One year of Ghanaian university study may allow direct Year 1. Foundation Year needs C6 in five subjects including English and Maths (STEM or Arts, Humanities and Social Sciences).", "pg": "Taught: bachelor from a recognised Ghanaian university, generally 2:2 (some courses 2:1 or work experience). Research MRes or PhD: minimum 2:1 or equivalent.", "english": "WASSC English at the required grade within the last 10 years may be enough. Otherwise a recognised English test; scores not on the Ghana page. Postgraduate research needs a test.", "how_to_apply": "Page refers to a separate How to Apply guide.", "documents": "Postgraduate research: research proposal, academic CV, passport scan, English test, budget sheet, degree certificates or transcripts.", "fees_link": "https://www.edgehill.ac.uk/departments/support/international/fees-and-scholarships/", "ghana_page_link": "https://www.edgehill.ac.uk/departments/support/international/your-country/ghana/", "sources": ["https://www.edgehill.ac.uk/departments/support/international/your-country/ghana/"]}$q$::jsonb, admission_link = $q$https://www.edgehill.ac.uk/departments/support/international/your-country/ghana/$q$, admission_checked = '2026-11-13' where id = 'fe1c96c5-b12f-493c-b433-9bf9b3b84836' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Four courses graded A or B with all others C or better; subject needs may apply. International Year One needs WASSCE; International Year Two needs 5 or more subjects at grades 1 to 6 plus one year higher study.", "pg": "Bachelor degree at 2:2 or above. International Incorporated Masters: HND over 70% or bachelor with third class.", "english": "UG: WASSCE English C6 or above within 2 years. PG: no test if bachelor was taught in English. Incorporated Masters IELTS 6.0 (one term) or 5.5 (two terms), 5.5 in each part. Year not stated.", "ghana_page_link": "https://www.napier.ac.uk/study-with-us/international-students/your-country/africa/ghana/entry-requirements", "sources": ["https://www.napier.ac.uk/study-with-us/international-students/your-country/africa/ghana/entry-requirements"]}$q$::jsonb, admission_link = $q$https://www.napier.ac.uk/study-with-us/international-students/your-country/africa/ghana/entry-requirements$q$, admission_checked = '2026-11-13' where id = '50603186-fe0f-4bc8-8d93-38cfc7d0eb54' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Recognised Foundation Diploma or foundation year, or Integrated Foundation Year with SSSC/WASSC, 12 years of school and minimum grade B in 5 subjects. Page does not name Ghana.", "pg": "Taught MA/MSc: a good honours bachelor or relevant experience. PhD: a Masters degree.", "english": "WAEC WASSCE or NECO English at C6 or above accepted for undergraduate, taught postgraduate and PhD. Other options on English page.", "how_to_apply": "Not stated; contact international@falmouth.ac.uk.", "ghana_page_link": "https://www.falmouth.ac.uk/international/entry-requirements", "sources": ["https://www.falmouth.ac.uk/international/entry-requirements"]}$q$::jsonb, admission_link = $q$https://www.falmouth.ac.uk/international/entry-requirements$q$, admission_checked = '2026-11-13' where id = '99ebb4ec-bc17-45b4-8efa-a02310f51efa' and country ilike 'United Kingdom';
update schools set admission_info = $q${"how_to_apply": "Ghana page offers an international applications guide and scholarship pages; contact international@gcu.ac.uk.", "deadlines": "Ghana page says tuition is from 15,200 GBP (year not stated) and links a separate deadlines page.", "ghana_page_link": "https://www.gcu.ac.uk/internationalstudy/your-region/country-pages/ghana", "sources": ["https://www.gcu.ac.uk/internationalstudy/your-region/country-pages/ghana"]}$q$::jsonb, admission_link = $q$https://www.gcu.ac.uk/internationalstudy/your-region/country-pages/ghana$q$, admission_checked = '2026-11-13' where id = '1f4b219b-d8da-4f54-94b2-e972ad9d9d41' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Direct entry with A levels, IB or a recognised Access or Foundation course. WASSCE not mentioned. Pre-programme courses exist for those who miss entry requirements.", "pg": "Taught: relevant bachelor degree. Research: relevant Masters. No classification stated.", "english": "Scores not on Ghana page; see English language requirements page.", "how_to_apply": "Undergraduate via UCAS. Postgraduate via apply now on programme page.", "deadlines": "Applications open 1 September for the next September; normal closing date 26 January, some courses to 30 June (year not named).", "documents": "Education history, personal statement, reference, extracurricular details.", "fees_link": "https://www.gold.ac.uk/fees-funding/", "ghana_page_link": "https://www.gold.ac.uk/international/regions/ghana/", "sources": ["https://www.gold.ac.uk/international/regions/ghana/"]}$q$::jsonb, admission_link = $q$https://www.gold.ac.uk/international/regions/ghana/$q$, admission_checked = '2026-11-13' where id = '137988d7-8611-4bf6-9a45-ca409ce67ac8' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "International qualifications are assessed per course page; Ghana not mentioned.", "english": "No scores on this page; English test or pre-sessional may be needed.", "how_to_apply": "Undergraduate through UCAS. Postgraduate apply direct via the university portal.", "deadlines": "September 2026 entry: course application 3 July 2026, pre-CAS interview 17 July, deposit 24 July, CAS request 31 July.", "documents": "Proof of qualifications, proof of English if needed.", "fees_link": "https://www.harper-adams.ac.uk/study/1075/finance/university-costs/", "sources": ["https://www.harper-adams.ac.uk/university-life/international/620/your-application/"]}$q$::jsonb, admission_link = $q$https://www.harper-adams.ac.uk/university-life/international/620/your-application/$q$, admission_checked = '2026-11-13' where id = '794586fb-1f9e-4bb4-893b-2d037a30aff6' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Undergraduate degree: West African Higher School Certificate. College A level route: WASSCE with grades A and B only. Top-up: Higher National Diploma. Year not stated.", "pg": "GPA 3.25/4 or 4.29/5 equals UK 2:1. GPA 2.5/4 or 2.8/5 equals UK 2:2.", "how_to_apply": "Page links to the Hartpury how to apply as an international student page.", "fees_link": "https://www.hartpury.ac.uk/university/student-life/fees-finance/", "ghana_page_link": "https://www.hartpury.ac.uk/university/international/international-students/your-country/ghana/", "sources": ["https://www.hartpury.ac.uk/university/international/international-students/your-country/ghana/"]}$q$::jsonb, admission_link = $q$https://www.hartpury.ac.uk/university/international/international-students/your-country/ghana/$q$, admission_checked = '2026-11-13' where id = '354be2a4-a251-4aa4-a5c6-450c4a477565' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana page has no Ghana detail. General: undergraduate qualifications dated within 5 years of start, foundation within 7 years. Contact studywithus@hw.ac.uk.", "english": "Foundation IELTS 5.5 (none below 5.5). Undergraduate IELTS 6.0 (5.5 each). Postgraduate taught non-STEM IELTS 6.0, writing 6.0. WAEC/WASSCE C6 listed for Ghana. Taught postgraduate: no time limit on WASSCE; Ghanaian degree taught in English accepted.", "ghana_page_link": "https://www.hw.ac.uk/study/international-students/study-in-the-uk/information-for-your-country", "sources": ["https://www.hw.ac.uk/study/international-students/study-in-the-uk/information-for-your-country", "https://www.hw.ac.uk/study/how-to-apply/entry-requirements/english-language-requirements"]}$q$::jsonb, admission_link = $q$https://www.hw.ac.uk/study/international-students/study-in-the-uk/information-for-your-country$q$, admission_checked = '2026-11-13' where id = '6ea0cd23-f96f-47fe-b160-c2a1b73d0263' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Varies by course; accepted international qualifications are on course pages. WASSCE not mentioned on the Africa page.", "pg": "Taught Masters from Ghana: minimum Lower Second Class Honours from a mainstream university, but Upper Second normally required for most courses. Doctorate needs a Masters.", "english": "Standard or Higher level by course. Undergraduate tests within two years of start. Some recognised high school English exams may be exempt.", "how_to_apply": "Undergraduate via UCAS, code I50, up to five courses. Postgraduate via Imperial online application.", "ghana_page_link": "https://www.imperial.ac.uk/study/international-students/information-by-region/africa/", "sources": ["https://www.imperial.ac.uk/study/international-students/information-by-region/africa/", "https://www.imperial.ac.uk/study/apply/postgraduate-taught/entry-requirements/accepted-qualifications/"]}$q$::jsonb, admission_link = $q$https://www.imperial.ac.uk/study/international-students/information-by-region/africa/$q$, admission_checked = '2026-11-13' where id = '9f7b0689-8405-4bf6-85f3-17fb108eef91' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Requirements vary by course; see International applicants on each course page. Ghana and WASSCE not mentioned on the page read.", "pg": "Ghana taught: four year bachelor from a recognised Ghanaian institution. High 2:1 equals GPA 3.5/5 or 80%; 2:1 equals GPA 3.25/5 or 70%; High 2:2 equals GPA 3.0/5 or 60%. Research: high grade two year Masters.", "english": "Usually needed; test or English in an accepted qualification. Scores are on a separate page.", "how_to_apply": "Undergraduate and postgraduate steps are on separate how to apply pages.", "sources": ["https://www.kcl.ac.uk/study-legacy/postgraduate/apply/entry-requirements/international", "https://www.kcl.ac.uk/study/undergraduate/how-to-apply/entry-requirements"]}$q$::jsonb, admission_link = $q$https://www.kcl.ac.uk/study-legacy/postgraduate/apply/entry-requirements/international$q$, admission_checked = '2026-11-13' where id = 'a4a3431f-ef33-4eac-8caf-f85c816f28b7' and country ilike 'United Kingdom';
update schools set admission_info = $q${"english": "IELTS: International Foundation Year 4.5, Foundation Diploma 5.0, International Year One 5.5, Pre-Masters 6.0, undergraduate 6.0 (5.5 each), postgraduate 6.5. Ghana and WAEC not mentioned.", "how_to_apply": "Ghana page lists in-country representatives and international@kingston.ac.uk; no steps.", "ghana_page_link": "https://kingston.ac.uk/international/country-specific-information/africa/ghana", "sources": ["https://kingston.ac.uk/international/country-specific-information/africa/ghana", "https://www.kingston.ac.uk/study/international-students/english-language-entry-requirements"]}$q$::jsonb, admission_link = $q$https://kingston.ac.uk/international/country-specific-information/africa/ghana$q$, admission_checked = '2026-11-13' where id = '3825c081-38c9-4e9f-b594-dd4c06621249' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Applicants who do not meet entry requirements can take an International Foundation programme. WASSCE grades not shown (page relates mainly to 2027 entry).", "pg": "Entry stated in UK classes (1st, 2:1, 2:2); Ghana equivalents not shown. Some courses need work experience or written work.", "how_to_apply": "Landing page lists routes for foundation, undergraduate and postgraduate; no steps.", "sources": ["https://www.lancaster.ac.uk/study/undergraduate/international-qualifications/", "https://www.lancaster.ac.uk/study/entry-requirements/postgraduate-qualifications/", "https://www.lancaster.ac.uk/study/international-students/how-to-apply-international/"]}$q$::jsonb, admission_link = $q$https://www.lancaster.ac.uk/study/undergraduate/international-qualifications/$q$, admission_checked = '2026-11-13' where id = '7ea3eb59-2d9e-4ddf-bc31-8417817f36bf' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSCE completed with 5 passes at C6 or above at enrolment (one set of requirements shown for all levels). Page does not separate undergraduate and postgraduate.", "english": "IELTS for UKVI 5.0 overall, no part below 4.5, or another accepted SELT.", "how_to_apply": "Apply via the Apply section of the website.", "documents": "Reference from a teacher, tutor or counsellor, and examples of work or an audition.", "ghana_page_link": "https://www.leeds-art.ac.uk/international/information-for-international-students/ghana", "sources": ["https://www.leeds-art.ac.uk/international/information-for-international-students/ghana"]}$q$::jsonb, admission_link = $q$https://www.leeds-art.ac.uk/international/information-for-international-students/ghana$q$, admission_checked = '2026-11-13' where id = 'c51b7314-d316-4d22-ad45-578aa26d0447' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Foundation: WASSCE with 5 passes at C6 or above. Undergraduate: National Diploma or GCE A Level at Lower Credit or UK A level equivalent grades.", "pg": "Bachelor degree: Second class lower (50%) for 2:2 courses, Second class upper (60%) for 2:1 courses.", "english": "Foundation IELTS 4.5 each skill. Undergraduate and postgraduate IELTS 6.0, no skill below 5.5, or WASSCE English C6.", "how_to_apply": "Page links to the Leeds Beckett how to apply page; steps not on it.", "documents": "Personal statements and references considered; no document list.", "fees_link": "https://www.leedsbeckett.ac.uk/international-students/course-fees-and-living-costs/", "ghana_page_link": "https://www.leedsbeckett.ac.uk/international-students/countries/ghana/ghana-entry-requirements/", "sources": ["https://www.leedsbeckett.ac.uk/international-students/countries/ghana/ghana-entry-requirements/"]}$q$::jsonb, admission_link = $q$https://www.leedsbeckett.ac.uk/international-students/countries/ghana/ghana-entry-requirements/$q$, admission_checked = '2026-11-13' where id = '36de4a32-7308-4197-bab0-5a7d54d99e9d' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Now Leeds Conservatoire. BA with Foundation Year (4 years): WASSCE with 5 subjects at C6, excluding native languages and vocational subjects. 3 year BA needs a Foundation Year.", "pg": "Masters (1 year MA): a bachelor degree. No classification stated.", "english": "Ghana page gives no scores. General: IELTS 6.0 overall, no sub-test below 5.5, PTE 60, LanguageCert 65, new TOEFL 4.5. Page does not mention WAEC.", "how_to_apply": "Classical and Jazz via UCAS Conservatoires code L31; other bachelor courses via UCAS code L30. Masters via direct form or UCAS Conservatoires L31. Audition or portfolio may follow.", "deadlines": "Not stated for Ghana.", "documents": "Audition, interview or portfolio as asked after applying.", "fees_link": "https://www.leedsconservatoire.ac.uk/courses/international-applicants/fees-funding/", "ghana_page_link": "https://www.leedsconservatoire.ac.uk/courses/international-applicants/your-region/africa/", "sources": ["https://www.leedsconservatoire.ac.uk/courses/international-applicants/your-region/africa/", "https://www.leedsconservatoire.ac.uk/courses/international-applicants/english-language-requirements/"]}$q$::jsonb, admission_link = $q$https://www.leedsconservatoire.ac.uk/courses/international-applicants/your-region/africa/$q$, admission_checked = '2026-11-13' where id = '82ed0208-9333-4f54-98f8-90e4d9cda2c9' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Applicants should not enter directly from the local school system. Need A levels, IB, or a recognised Foundation Year at another provider. Page says applications from Ghana are closed for Sept 2026, Jan 2027 and Sept 2027 intakes.", "pg": "Honours bachelor degree, minimum 2:2.", "english": "No scores on Ghana page; see English language requirements page.", "how_to_apply": "Page links undergraduate and postgraduate application pages; Africa team africa@leedstrinity.ac.uk.", "deadlines": "Ghana applications closed for September 2026, January 2027 and September 2027 intakes.", "fees_link": "https://www.leedstrinity.ac.uk/international/international-fees-and-funding/", "ghana_page_link": "https://www.leedstrinity.ac.uk/international/your-country-or-region/ghana/", "sources": ["https://www.leedstrinity.ac.uk/international/your-country-or-region/ghana/"]}$q$::jsonb, admission_link = $q$https://www.leedstrinity.ac.uk/international/your-country-or-region/ghana/$q$, admission_checked = '2026-11-13' where id = '4e1e7b86-b62e-4c64-aec2-ac2e8ea51efc' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana page lists Higher National Diploma, or an international foundation year from a UK institution following a validated UK syllabus. WASSCE grades are not stated on the page.", "pg": "Bachelor degree with minimum 2nd Class Lower Division.", "english": "Scores not on the Ghana page; it links to a separate English Language Requirements page.", "how_to_apply": "Ghana page links to an international Apply now page. Application help email listed: lincolnbishopadmissions@oxfordinternational.com.", "ghana_page_link": "https://www.lincolnbishop.ac.uk/international/entry-requirements/ghana", "sources": ["https://www.lincolnbishop.ac.uk/international/entry-requirements/ghana"]}$q$::jsonb, admission_link = $q$https://www.lincolnbishop.ac.uk/international/entry-requirements/ghana$q$, admission_checked = '2026-11-13' where id = 'fc9cd755-1aae-486d-afdf-394431413b1f' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "SSCE/WASSCE plus a recognised foundation year, or SSCE/WASSCE plus first year of a recognised university degree. Also normally West Africa Higher School Certificate, or OND/HND from a recognised Ghanaian institution. Grades not stated.", "pg": "Taught masters: 'a good honours degree'. Class not stated. Research degrees: see postgraduate research pages.", "english": "Not stated on Ghana page; separate English Language Requirements page is linked.", "how_to_apply": "Not stated on page; a separate How to Apply page is linked. Page warns Ghana applicants face extra checks and a CAS may not always be issued; contact Admissions before applying. Page shows 2026/27 international fees: UG GBP 15,225; PGT from GBP 15,250.", "fees_link": "https://www.hope.ac.uk/international/yourcountryregion/ghana/", "ghana_page_link": "https://www.hope.ac.uk/international/yourcountryregion/ghana/", "sources": ["https://www.hope.ac.uk/international/yourcountryregion/ghana/"]}$q$::jsonb, admission_link = $q$https://www.hope.ac.uk/international/yourcountryregion/ghana/$q$, admission_checked = '2026-11-13' where id = '5028aad2-ef93-49fc-a5b1-d912b65e7c00' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "First-year entry needs a university Diploma or HND at grade 2.2 or above. Recognised international foundation years also accepted. WASSCE grades not stated. Page says this is a general guide and varies by course.", "pg": "Second-class bachelor degree from a recognised institution.", "ghana_page_link": "https://ljmu.ac.uk/study/courses/international-entry-requirements/ghana", "sources": ["https://ljmu.ac.uk/study/courses/international-entry-requirements/ghana"]}$q$::jsonb, admission_link = $q$https://ljmu.ac.uk/study/courses/international-entry-requirements/ghana$q$, admission_checked = '2026-11-13' where id = '2a60932d-50f8-4cce-86b3-27f3bd854ac2' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Diploma with minimum CGPA/FGPA 2.7. Applicants with exceptional SSSCE grades (all A/B) may be considered. Slightly below standard may be considered for a foundation year degree. SSSCE Maths A1 to C6 where relevant. 2026-27 page.", "pg": "Second class degree or CGPA/FGPA 2.7 minimum for masters. Institution minimums listed, e.g. Legon CGPA 2.50 to 2.70, KNUST CWA 50 to 60 percent.", "english": "WAEC SSCE grade C6 (2006 onward) accepted as equal to IELTS 6.0 overall with 5.5 in each band. Courses with higher needs listed on course pages.", "how_to_apply": "Undergraduate: UCAS or direct via the Applicant Portal (Apply now on course page). Postgraduate: direct via the Applicant Portal.", "deadlines": "Dates not stated on the page; it links to an Application dates and deadlines page.", "ghana_page_link": "https://londonmet.ac.uk/international/applying/entry-requirements-by-country/ghana", "sources": ["https://londonmet.ac.uk/international/applying/entry-requirements-by-country/ghana"]}$q$::jsonb, admission_link = $q$https://londonmet.ac.uk/international/applying/entry-requirements-by-country/ghana$q$, admission_checked = '2026-11-13' where id = 'c7e5b00b-3c98-4941-9ebb-6c765089c0d5' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Foundation: WASSC with C6 or above in 5-6 subjects incl English and Maths. Year one of degree: completed Level 100 of a Ghanaian bachelor degree. Year two: HND (credit) or Levels 100 and 200 completed. Also accepts UK foundation (60%), IB 24 points.", "pg": "Four or five year bachelor degree from a recognised Ghanaian university; most courses need minimum Second Class Lower Division.", "english": "IELTS 4.5 (foundation), 6.0 (undergraduate), 6.5 (postgraduate) or equivalent. Other accepted tests listed in a PDF; contact international office.", "how_to_apply": "Process differs for UG and PG; steps not described on the page.", "ghana_page_link": "https://www.lsbu.ac.uk/international/your-country/africa/ghana", "sources": ["https://www.lsbu.ac.uk/international/your-country/africa/ghana"]}$q$::jsonb, admission_link = $q$https://www.lsbu.ac.uk/international/your-country/africa/ghana$q$, admission_checked = '2026-11-13' where id = 'ba9362a8-72d4-4170-b7e1-19abaea8ba72' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSCE students need a suitable Foundation Year (Loughborough offers one via ONCAMPUS). A Level or IB may be considered for direct entry. No WASSCE grades listed.", "pg": "Degree equivalents: first class = 65% or 3.4 GPA; upper second = 57% or 3.0 GPA; lower second = 50% or 2.5 GPA.", "english": "Must meet University English requirements; scores not stated on this page, linked separately.", "how_to_apply": "Not stated; links to a general How to apply page.", "ghana_page_link": "https://lboro.ac.uk/international/country/ghana/applicationinformation/entryrequirements/", "sources": ["https://lboro.ac.uk/international/country/ghana/applicationinformation/entryrequirements/"]}$q$::jsonb, admission_link = $q$https://lboro.ac.uk/international/country/ghana/applicationinformation/entryrequirements/$q$, admission_checked = '2026-11-13' where id = 'd5982cd4-0fb3-4fa1-81ee-664adaa912c6' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Foundation: SSCE/WAEC with minimum C6 in 5 subjects incl English Language and Maths. Degree: SSCE/WAEC plus a recognised foundation year. Year 2 or 3 top-up: HND with minimum GPA 2.5 out of 4.", "pg": "Bachelor degree from a recognised Ghanaian university with minimum GPA 2.5 out of 4. Class not stated.", "english": "UG: IELTS 6.0 (no part below 5.5). PG: IELTS 6.5 (no part below 5.5). WAEC/WASSCE C6 in English accepted as alternative. Some PG courses need more.", "how_to_apply": "Page links to applying through an education agent and visa guidance; no steps given.", "ghana_page_link": "https://mmu.ac.uk/study/international/international-students/ghana", "sources": ["https://mmu.ac.uk/study/international/international-students/ghana"]}$q$::jsonb, admission_link = $q$https://mmu.ac.uk/study/international/international-students/ghana$q$, admission_checked = '2026-11-13' where id = '39412e88-a50b-4276-9f39-3edafa39aa61' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Most courses: SSCE plus a recognised one-year foundation, GCE A-levels, AVCE, or a University of Ghana/UST diploma. SSCE only: may be considered for the Middlesex International Foundation Programme. Course grades vary.", "pg": "Good bachelor degree equal to UK second class honours. MBA needs 2 years management experience; GMAT over 550 sometimes.", "english": "Must meet standard Middlesex English requirements; scores not on this page. Pre-sessional English offered.", "how_to_apply": "Undergraduate via UCAS. Postgraduate via the Middlesex Applicant Portal.", "documents": "At visa stage: CAS, passport, academic documents, English evidence, finance evidence, ATAS if needed.", "fees_link": "https://www.mdx.ac.uk/international/course-fees-and-costs-for-international-students/", "ghana_page_link": "https://www.mdx.ac.uk/international/support-in-your-countries-and-regions/ghana/", "sources": ["https://www.mdx.ac.uk/international/support-in-your-countries-and-regions/ghana/"]}$q$::jsonb, admission_link = $q$https://www.mdx.ac.uk/international/support-in-your-countries-and-regions/ghana/$q$, admission_checked = '2026-11-13' where id = '20931b39-41df-4c17-834e-cffcc3f71e23' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSC/SSCE/WAHSC with a grade B/C profile, or plus a recognised foundation programme, or first year of a recognised university degree.", "pg": "Bachelor degree with minimum 2nd Class Lower Division.", "english": "UG IELTS for UKVI 6.0 (none below 5.5); PG 6.5 (none below 6.0); foundation 5.5 each. Must be a SELT within 2 years unless exempt.", "how_to_apply": "Apply button on course page with documents. Applicants must be 18+. Pre-CAS credibility interview required, then tuition deposit per offer letter.", "deadlines": "No application deadline stated. Starts: September, November, January. Visa within 3 months of start; at least 50 percent fees paid at enrolment.", "documents": "Online application, personal statement, certified certificates and transcripts (certified translation if needed), SELT evidence, references (1 for UG, 2 for PG).", "fees_link": "https://newman.ac.uk/international-students/international-tuition-fees-and-scholarships/", "sources": ["https://newman.ac.uk/international-students/entry-requirements-and-visa-information/", "https://newman.ac.uk/international-students/international-tuition-fees-and-scholarships/"]}$q$::jsonb, admission_link = $q$https://newman.ac.uk/international-students/entry-requirements-and-visa-information/$q$, admission_checked = '2026-11-13' where id = 'c3be4dce-2e9c-4f88-b6d9-bddea073243d' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana: Integrated Foundation Year needs WASSCE with minimum C6 in 5 subjects. Year 1: HND pass, or one year of a bachelor degree at 60% or 3.25 (table ambiguous). Year 2: HND pass, course team discretion.", "pg": "Bachelor degree with minimum 60% or 3.25 from a recognised institution.", "english": "Not on this page; separate English requirements page linked.", "how_to_apply": "See How to apply as an international applicant page (not read in detail).", "documents": "Certified translations needed if documents not in English.", "fees_link": "https://norwichuni.ac.uk/international-students/fees-finance-scholarships/", "sources": ["https://norwichuni.ac.uk/international-students/academic-requirements/"]}$q$::jsonb, admission_link = $q$https://norwichuni.ac.uk/international-students/academic-requirements/$q$, admission_checked = '2026-11-13' where id = 'a38c2aea-79f7-4dbc-b92c-21ce5c59cb51' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSCE accepted with grade C6. May be considered for foundation at Nottingham Trent International College, or second-year entry.", "pg": "Masters, pre-masters and research listed; specific entry not stated.", "english": "Scores not stated; pre-sessional English (PEAP) available.", "how_to_apply": "Steps not stated. Contact africa@ntu.ac.uk if qualification not listed.", "documents": "WASSCE scratch card must be provided with the application.", "ghana_page_link": "https://www.ntu.ac.uk/international/countries/africa/ghana", "sources": ["https://www.ntu.ac.uk/international/countries/africa/ghana"]}$q$::jsonb, admission_link = $q$https://www.ntu.ac.uk/international/countries/africa/ghana$q$, admission_checked = '2026-11-13' where id = '4980c212-d9a5-4a5d-89c1-7bfa05c61427' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSCE plus a recognised foundation course counts as A-level equivalent. Integrated 4-year foundation: five B grades. International Foundation Diploma: five C grades. Below minimum may still apply for foundation.", "pg": "Bachelor degree; 2:1 and 2:2 Ghana equivalents are same class for direct entry; Pass (3rd class) for pre-masters. Check course page.", "english": "IELTS 6.0 to 7.0 (6.0 reading/writing, 5.5 listening/speaking), or pre-sessional, or WASSCE English C6 verified by scratch card.", "documents": "WAEC scratch card to verify results.", "ghana_page_link": "https://www.brookes.ac.uk/study/international-students/your-country/ghana/entry-requirements", "sources": ["https://www.brookes.ac.uk/study/international-students/your-country/ghana/entry-requirements"]}$q$::jsonb, admission_link = $q$https://www.brookes.ac.uk/study/international-students/your-country/ghana/entry-requirements$q$, admission_checked = '2026-11-13' where id = '2c488b63-d6f8-4559-9f19-eba5506931af' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Foundation entry: WAEC senior school certificate with grades 1-8 in 4 relevant subjects. Undergraduate entry: National Diploma with grade C or above.", "pg": "Pre-Masters: 3rd class bachelors. Masters: bachelors 2:2 or above or GPA 2.51+, or 3rd class plus 2 years relevant work experience.", "english": "Scores not on Ghana page; it links to a separate English language requirements page.", "how_to_apply": "Page says direct applications from Ghana cannot be accepted; apply through an authorised representative (agencies listed on the page).", "fees_link": "https://wrexham.ac.uk/international-students/international-fees/", "ghana_page_link": "https://wrexham.ac.uk/international-students/international-academic-entry-requirements/ghana", "sources": ["https://wrexham.ac.uk/international-students/international-academic-entry-requirements/ghana"]}$q$::jsonb, admission_link = $q$https://wrexham.ac.uk/international-students/international-academic-entry-requirements/ghana$q$, admission_checked = '2026-11-13' where id = '1cf18cd2-2cad-4afb-8f56-1b8e7b4d3522' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Arts, Social Sciences, Management: WASSCE with 7 subjects, B3 or above in four and C6 or above in the rest (B2 if a subject is specified). Health Sciences: WASSCE alone not accepted; need a diploma, A Levels, IB, or a recognised foundation.", "pg": "A good bachelors degree from a recognised university. Class not stated. Statement of purpose, work experience or subjects may be needed.", "english": "UG: WASSCE English C6 or above within last two years. PG: if degree studied in Ghana, usually no further English test needed.", "how_to_apply": "See QMU How to apply page (linked from the Ghana page). Ghana-based applicants must pay first-year tuition in full before CAS is issued.", "fees_link": "https://www.qmu.ac.uk/study-here/fees-and-funding", "ghana_page_link": "https://www.qmu.ac.uk/study-here/international-students/information-for-your-country/ghana", "sources": ["https://www.qmu.ac.uk/study-here/international-students/information-for-your-country/ghana"]}$q$::jsonb, admission_link = $q$https://www.qmu.ac.uk/study-here/international-students/information-for-your-country/ghana$q$, admission_checked = '2026-11-13' where id = '5293886c-157c-4620-a66b-ff5b1cddf859' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Foundation courses consider the West African Senior School Certificate. Direct entry considered with A-Levels or IB or recognised foundation qualifications. WASSCE grades not stated.", "pg": "Bachelor degree from a recognised institution. UK equivalents listed: First = 1st, Second Upper = 2:1, Second Lower = 2:2.", "english": "Not stated on Ghana page; links to separate English requirements pages.", "how_to_apply": "How to apply links are given for UG and PGT; steps not on this page.", "fees_link": "https://www.qmul.ac.uk/international-students/tuitionfees/", "ghana_page_link": "https://qmul.ac.uk/international-students/regions/africa/entry-requirements/ghana", "sources": ["https://qmul.ac.uk/international-students/regions/africa/entry-requirements/ghana"]}$q$::jsonb, admission_link = $q$https://qmul.ac.uk/international-students/regions/africa/entry-requirements/ghana$q$, admission_checked = '2026-11-13' where id = 'ec2db1ae-597f-42d1-b3a8-f73e0525be86' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WAEC SSCE holders must complete a Foundation Programme. Ghanaian HND with CGPA 3.0 (upper credit) or above, or first year of a relevant Ghanaian degree, may get first-year entry. Also 3 UK A Levels or IB 30 to 36. Grades vary by course.", "pg": "UK 2:1 or 2:2 usually needed for taught masters; Ghanaian Second Class Upper or Lower bachelor degree compared. PhD needs good bachelor and masters grades plus research proposal.", "english": "WASSCE/WAEC taken within last 7 years accepted. Ghanaian degrees from recognised institutions accepted for PG. Typically IELTS 6.5 or TOEFL iBT 90, some courses differ.", "how_to_apply": "UG: mostly UCAS. PGT and PhD: Queen's online portal. Foundation: via Queen's University Belfast International Study Centre.", "deadlines": "UG (UCAS) international deadline 30 June 2027. Masters start September; no PG deadline stated. PhD start agreed with supervisor.", "application_fee": "Postgraduate: no application fee. Undergraduate: not stated.", "documents": "Official transcripts (completed and in progress) and degree certificates.", "ghana_page_link": "https://www.qub.ac.uk/Study/international-students/your-country/ghana", "sources": ["https://www.qub.ac.uk/Study/international-students/your-country/ghana", "https://www.qub.ac.uk/Study/international-students/your-country/nigeria"]}$q$::jsonb, admission_link = $q$https://www.qub.ac.uk/Study/international-students/your-country/ghana$q$, admission_checked = '2026-11-13' where id = '43354e7a-e947-4a4b-9109-6282a1472790' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Results comparable to UK students, case by case. No subject-level WASSCE grades stated. Without an international high school qualification, a pathway programme at RGU International College is needed.", "pg": "First degree at least second class lower or CGPA 2.51. KNUST: 50-59% or Grade C. Univ of Ghana: 65% or C+ or CGPA 2.51. Few courses need second class upper. Pre-masters available.", "english": "UG: IELTS 6.0 (5.5 each band) usual; PG: IELTS 6.5 (5.5 each band) usual. WAEC/WASSCE English C6 or above also accepted.", "how_to_apply": "Use the Apply Now link at rgu.ac.uk/apply. Approved agents in Ghana can help. Contact admissions@rgu.ac.uk.", "ghana_page_link": "https://rgu.ac.uk/study/international-students/your-country-or-territory/ghana", "sources": ["https://rgu.ac.uk/study/international-students/your-country-or-territory/ghana"]}$q$::jsonb, admission_link = $q$https://rgu.ac.uk/study/international-students/your-country-or-territory/ghana$q$, admission_checked = '2026-11-13' where id = 'd567a47a-33a5-4783-a883-d90685593bfc' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Bachelors: grade D or above in 5 subjects on WASSCE plus a diploma with at least lower credit or an OND. Foundation (IFP): WAEC, 5 subjects at grade 6. Page says guidelines only; pre-CAS interview expected.", "pg": "Taught masters: second class lower division or GPA 3.0/5.0. Research (PhD, PsychD): Masters with Merit.", "english": "Bachelors: WAEC English C6 or IELTS 6.0 (5.5 each). Masters: WAEC C6 or IELTS 6.5 (5.5 each; 7.0 for research). PhD: IELTS 7.0. Medium of instruction letter also accepted.", "how_to_apply": "Page links to a How to Apply section; steps not described.", "deadlines": "No application deadline stated. Accommodation guaranteed if Sept applicants apply before 31 July.", "ghana_page_link": "https://www.roehampton.ac.uk/international/countries/ghana/", "sources": ["https://www.roehampton.ac.uk/international/countries/ghana/"]}$q$::jsonb, admission_link = $q$https://www.roehampton.ac.uk/international/countries/ghana/$q$, admission_checked = '2026-11-13' where id = 'ba192f08-58a1-4e38-a2f7-9fe75ebf0cbf' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSCE or NECO holders must complete an International Foundation Year first. Diploma with Merit in agriculture, horticulture or forestry from listed Ghanaian institutions may enter the foundation degree. A-levels considered.", "pg": "Taught MSc/MBA: UK bachelors honours 2:2 or higher, or a bachelors degree. MSc by Research: 2:1 in relevant subject or a bachelors degree. PhD: masters or bachelors.", "english": "UG: IELTS Academic 6.0 (5.5 each) within 2 years; SELT for foundation degree. PGT: 6.5 (5.5 each). Research: 6.5 (6.0 writing).", "how_to_apply": "UG via UCAS. PG directly through the online form on the course page.", "ghana_page_link": "https://www.rau.ac.uk/study/international-students/your-country/ghana", "sources": ["https://www.rau.ac.uk/study/international-students/your-country/ghana"]}$q$::jsonb, admission_link = $q$https://www.rau.ac.uk/study/international-students/your-country/ghana$q$, admission_checked = '2026-11-13' where id = '232da8e0-4beb-4cff-beda-e7ef293639cc' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Secondary school diploma holders need International Foundation Year or International Year One. One year of a Ghanaian bachelors with good grades may get direct first-year entry. A levels/IB considered. WASSCE grades not stated.", "pg": "Bachelors with good grades; most departments ask for second class upper or lower or equivalent. Pre-Masters offered if slightly below.", "english": "Minimum English level required; scores not on this page. Ghanaian bachelors holders meet the PG English requirement. Pre-sessional available.", "how_to_apply": "UG via UCAS. Foundation courses directly to Royal Holloway. PG directly to Royal Holloway.", "fees_link": "https://www.royalholloway.ac.uk/studying-here/fees-and-funding/international-student-fees", "ghana_page_link": "https://royalholloway.ac.uk/studying-here/international-students/find-your-country/ghana", "sources": ["https://royalholloway.ac.uk/studying-here/international-students/find-your-country/ghana"]}$q$::jsonb, admission_link = $q$https://royalholloway.ac.uk/studying-here/international-students/find-your-country/ghana$q$, admission_checked = '2026-11-13' where id = 'd2dc287f-fd70-4fa2-b9a8-a94535227446' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "No Ghana page found. General page: undergraduate applicants apply via UCAS; entry requirements vary by course (see course pages).", "pg": "Entry requirements vary by course; see postgraduate course pages.", "how_to_apply": "Undergraduate via UCAS (general international page). Questions: admissions@rvc.ac.uk.", "sources": ["https://rvc.ac.uk/study/international-students/how-to-apply"]}$q$::jsonb, admission_link = $q$https://rvc.ac.uk/study/international-students/how-to-apply$q$, admission_checked = '2026-11-13' where id = 'fd0aae89-3a9a-4b50-b2b7-cbc265679516' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Year 1: A-levels or IB at good grades (see course pages). West African Senior School Certificate holders considered for the International Foundation Programme. NCUK IFY considered. HND may enter top-up or Level 4/5. WASSCE grades not stated.", "pg": "Four-year bachelor degree considered; Higher Diploma with significant work experience considered. Class not stated. PhD needs a masters degree and research proposal.", "english": "WASSCE English C6 accepted in place of IELTS 6.0 (5.5 each skill) for Year 1; same C6 accepted for Year 2 or 3.", "fees_link": "https://www.shu.ac.uk/study-here/fees-and-funding", "ghana_page_link": "https://www.shu.ac.uk/study-here/international/entry-requirements/entry-requirements-for-ghana", "sources": ["https://www.shu.ac.uk/study-here/international/entry-requirements/entry-requirements-for-ghana"]}$q$::jsonb, admission_link = $q$https://www.shu.ac.uk/study-here/international/entry-requirements/entry-requirements-for-ghana$q$, admission_checked = '2026-11-13' where id = 'db9eafae-1e59-46a1-a454-b5d99c453c6f' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Looks for qualifications equivalent to British A-levels; page says applicants should hold West African Higher School Certificate or GCE A-levels. WASSCE grades not stated.", "pg": "Qualifications equivalent to a British bachelor degree. Class not stated.", "english": "Not stated; page links to a pre-sessional English programme.", "how_to_apply": "Apply directly (page says most find it easy). After conditions met and deposit paid, a CAS number is issued for the visa.", "documents": "CAS number for visa; portfolio for most art and design courses.", "fees_link": "https://www.solent.ac.uk/finance/tuition-fees", "ghana_page_link": "https://www.solent.ac.uk/international/your-country/ghana", "sources": ["https://www.solent.ac.uk/international/your-country/ghana"]}$q$::jsonb, admission_link = $q$https://www.solent.ac.uk/international/your-country/ghana$q$, admission_checked = '2026-11-13' where id = '41dd8aa0-4acd-46fd-98b5-81b3f0bd5e5b' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSC holders normally considered for the St Mary's Foundation programme or equivalent. First year of a Ghanaian bachelors with good grades considered for first-year entry. WASSCE grades not stated.", "pg": "Bachelors from a recognised institution. 2:1 = Ghanaian 2:1 or GPA 3.25; 2:2 = Ghanaian 2:2 or GPA 2.5. Relevant work experience considered.", "english": "WASSCE/WAEC with C4 in English accepted. Other tests accepted but not named. Pre-sessional offered. Conditional offers can be given before English is met.", "how_to_apply": "Apply online using the step-by-step guides for UG, PG and PGCE (linked on the page).", "documents": "Documents meeting UK visa rules, existing English test results, personal statement, qualifications.", "fees_link": "https://www.stmarys.ac.uk/fees/2026-27-tuition-fees-for-international-students", "ghana_page_link": "https://www.stmarys.ac.uk/international/country-information/ghana", "sources": ["https://www.stmarys.ac.uk/international/country-information/ghana"]}$q$::jsonb, admission_link = $q$https://www.stmarys.ac.uk/international/country-information/ghana$q$, admission_checked = '2026-11-13' where id = '0dcd0365-b6b8-4b31-9d06-da7688de9fb0' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSCE not listed. Ghanaian HND or Diploma accepted with overall 2.51 / Second Class Lower / 50 (diploma after at least 2 years at a public university). Foundation or pathway applicants apply to The College, Swansea University.", "pg": "Not stated on the Ghana page; it links to a country-specific postgraduate entry page.", "english": "Not stated on these pages; refers to the University English Language requirements page.", "how_to_apply": "Apply through the Learner Gateway Application Portal; send transcripts and a personal statement. Offers can take up to 15 days.", "deadlines": "No deadline stated; apply early for scholarship consideration.", "documents": "Transcripts and personal statement.", "ghana_page_link": "https://www.swansea.ac.uk/international-students/my-country/ghana/", "sources": ["https://www.swansea.ac.uk/international-students/my-country/ghana/", "https://www.swansea.ac.uk/international-students/international-student-courses/undergraduate-international-entry-requirements/"]}$q$::jsonb, admission_link = $q$https://www.swansea.ac.uk/international-students/my-country/ghana/$q$, admission_checked = '2026-11-13' where id = 'a9d3f1d2-a69d-43ff-a540-2fba36a9da47' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Year 1: GCE A-level at standard UK requirements, or a diploma with lower credit minimum (higher credit for Integrated MEng). HND may enter Year 2 with GPA 3.0/5.0 or Year 3 with 4.0/5.0. Foundation: case by case. WASSCE not mentioned.", "pg": "2.2 at undergraduate degree or 2.5/4 GPA.", "english": "Not stated; links to English admissions and testing page.", "how_to_apply": "Page links to a How to apply section; steps not given.", "deadlines": "No dates on the Ghana page; links to Key deadlines page.", "documents": "Page links to qualification verification and CAS pages.", "fees_link": "https://www.tees.ac.uk/sections/international/fees.cfm", "ghana_page_link": "https://www.tees.ac.uk/sections/international/country_details.cfm?country_id=24", "sources": ["https://www.tees.ac.uk/sections/international/country_details.cfm?country_id=24", "https://www.tees.ac.uk/sections/international/entry-requirements.cfm", "https://www.tees.ac.uk/sections/international/country.cfm"]}$q$::jsonb, admission_link = $q$https://www.tees.ac.uk/sections/international/country_details.cfm?country_id=24$q$, admission_checked = '2026-11-13' where id = 'aa972233-a746-48f5-8c82-a7db56b7dca1' and country ilike 'United Kingdom';
update schools set admission_info = $q${"how_to_apply": "General page only: full-time UG via UCAS (code P56). For international applicants contact admissions@ucp.ac.uk.", "deadlines": "Page mentions the first UCAS deadline 15 January.", "sources": ["https://ucp.ac.uk/how-to-apply/"]}$q$::jsonb, admission_link = $q$https://ucp.ac.uk/how-to-apply/$q$, admission_checked = '2026-11-13' where id = 'b3f47d0d-1a53-40a1-bcd3-1434343f6d91' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSCE grades A to C in at least five subjects incl Maths and English plus course subjects. Diploma with overall 50% considered for a degree. HND accepted for advanced standing. IB 24 points.", "pg": "Page names no degree class for masters entry; MSc Finance and Accounting needs a related degree.", "english": "WASSCE English minimum C6. Qualification must be from last 10 years, else UCB English Proficiency Test.", "how_to_apply": "Direct applications from Ghana welcome. UCB recommends a Ghana representative (AIMS Education, Excel-Plus Education, International Studies, UKEAS Ghana).", "deadlines": "Not stated on the page; site has a Deadlines page.", "fees_link": "https://www.ucb.ac.uk/international/international-tuition-fees/", "ghana_page_link": "https://www.ucb.ac.uk/international/country-and-territory-information/ghana/", "sources": ["https://www.ucb.ac.uk/international/country-and-territory-information/ghana/"]}$q$::jsonb, admission_link = $q$https://www.ucb.ac.uk/international/country-and-territory-information/ghana/$q$, admission_checked = '2026-11-13' where id = 'd4454705-0bc2-47c8-932f-a6ecacfaee4a' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "A levels ABB (2026 entry) or equivalent. Alternatively two years of a bachelors at a Ghanaian university recognised by UCL with an upper second class average. Course requirements may be higher. WASSCE not mentioned.", "pg": "Usually upper second (2:1) or lower second (2:2) bachelors from a public university, depending on programme. Doctoral: masters also needed.", "ghana_page_link": "https://www.ucl.ac.uk/digital-presence-services/webapps/www/international-country-information.php?country=ghana", "sources": ["https://www.ucl.ac.uk/digital-presence-services/webapps/www/international-country-information.php?country=ghana"]}$q$::jsonb, admission_link = $q$https://www.ucl.ac.uk/digital-presence-services/webapps/www/international-country-information.php?country=ghana$q$, admission_checked = '2026-11-13' where id = '1ac08b8b-eb7d-4d56-8490-68fb3580f7e1' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Five SSSCE passes at grade B or above, or Ghanaian HND (year 1/2 or top-up), or one year of university with GPA 3.0+. Foundation: five SSSCE passes at C or above.", "pg": "Completed bachelors from a recognised university. Class not stated. Integrated Pre-Masters: Ghana HND.", "english": "IELTS UG 6.0 (5.5 each); UG with foundation year 5.5; International Foundation 5.0; Masters 6.5 (5.5 each) or WAEC English C6 for masters.", "how_to_apply": "Not stated; contact the country manager or international admissions (internationaladmissions@uca.ac.uk).", "ghana_page_link": "https://ucreative.ac.uk/international/countries/ghana/", "sources": ["https://ucreative.ac.uk/international/countries/ghana/"]}$q$::jsonb, admission_link = $q$https://ucreative.ac.uk/international/countries/ghana/$q$, admission_checked = '2026-11-13' where id = 'c8b0c546-d338-40d4-9907-e4013f50db34' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Direct Year 1 entry with at least one A and two Bs in WASSCE (not Medicine). Subject needs vary (e.g. Engineering: English, Maths, Physics). Others take a Foundation Year via the International Study Centre. Guide only.", "pg": "Bachelors from a recognised institution. 2:1 = 60 to 70 percent or CGPA 3.00 to 3.49; 2:2 = 50 to 59 percent or CGPA 2.5 to 2.99.", "english": "Page links to accepted high school English grades and approved medium of instruction universities; scores not stated on page.", "ghana_page_link": "https://www.abdn.ac.uk/study/international/country-territory/ghana/entry/", "sources": ["https://www.abdn.ac.uk/study/international/country-territory/ghana/entry/"]}$q$::jsonb, admission_link = $q$https://www.abdn.ac.uk/study/international/country-territory/ghana/entry/$q$, admission_checked = '2026-11-13' where id = '02b66da8-18c0-4b4d-b916-fb006f2a72fd' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "No Ghana-specific requirements found on the pages read. Page says if your country is not listed you can still apply, and lists Agents in Africa.", "english": "English Category B page lists West African Senior School Certificate Examination English at Grade B3 for all nationalities (Ghana not named).", "how_to_apply": "Page links to how to apply for UG and taught PG courses.", "deadlines": "Page links to important dates for 2026 applications.", "fees_link": "https://www.bath.ac.uk/topics/tuition-fees/", "sources": ["https://www.bath.ac.uk/corporate-information/entry-requirements-for-international-students/", "https://www.bath.ac.uk/corporate-information/english-language-requirements-for-qualifications-category-b/"]}$q$::jsonb, admission_link = $q$https://www.bath.ac.uk/corporate-information/entry-requirements-for-international-students/$q$, admission_checked = '2026-11-13' where id = '020fbf24-f98a-44fb-9f13-cd1362f203d5' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WAEC/NECO: 5 subjects at C6 minimum (or 3 credits with one at C or above, per page). Also 2 A level passes (C and D), IB 24 points, or a recognised Foundation degree.", "pg": "Page lists UK honours bachelors 2:2 minimum and GPA equal to 50 percent minimum (level not specified on page).", "english": "Not stated; page refers to a separate International entry requirements page.", "how_to_apply": "Apply directly via Apply now on the course page, or via UCAS for undergraduate courses.", "ghana_page_link": "https://beds.ac.uk/international/countries/ghana", "sources": ["https://beds.ac.uk/international/countries/ghana"]}$q$::jsonb, admission_link = $q$https://beds.ac.uk/international/countries/ghana$q$, admission_checked = '2026-11-13' where id = 'cb36622d-5e57-4ebd-ad31-a25574c4e9e8' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghanaian applicants need A Levels, IB or a suitable foundation programme. UoB Foundation Pathways need WAEC SSCE with 5 subjects at B3, including B3 Maths for Engineering and Physical Sciences. HND or first year of a Ghanaian degree (2.1, 3.0/4.0, 3.5/5.0) may be considered for first year entry.", "pg": "Most taught Masters need a minimum upper second class (2.1) degree, GPA at least 3.0/4.0 or 3.5/5.0. PG Diploma/Masters need a recognised Bachelor degree. PhD needs a Masters.", "english": "UG and foundation: WAEC SSCE English grade C or above (numerical 6 or above). PG: Ghanaian nationals with a degree from Ghana or an approved English-speaking country need no English test.", "how_to_apply": "Apply through the University's international Apply now page (link on Ghana page). Page gives no steps.", "ghana_page_link": "https://www.birmingham.ac.uk/international/students/country/ghana", "sources": ["https://www.birmingham.ac.uk/international/students/country/ghana"]}$q$::jsonb, admission_link = $q$https://www.birmingham.ac.uk/international/students/country/ghana$q$, admission_checked = '2026-11-13' where id = '20c8103c-7381-4c05-abf6-dbdc42370a45' and country ilike 'United Kingdom';
update schools set admission_info = $q${"english": "See English language page (scores not read).", "deadlines": "Ghana page says Bradford has temporarily paused UG and PGT applications from Ghana for the January 2027 intake. PhD, distance learning, UBIC pathway progression and applicants already holding a CAS may proceed. Page says pause will be reviewed regularly.", "ghana_page_link": "https://bradford.ac.uk/international/country/ghana", "sources": ["https://bradford.ac.uk/international/country/ghana"]}$q$::jsonb, admission_link = $q$https://bradford.ac.uk/international/country/ghana$q$, admission_checked = '2026-11-13' where id = '0a596cd2-3060-40dc-9d23-37022cfedb9f' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana page: good (3/B or above) Senior Secondary School Certificate plus an acceptable international foundation year or equivalent. West African Higher School Certificate or GCE A Levels meet UG requirements.", "pg": "Good honours degree, at least 2.2, from a central university in Ghana (page gives 1st, 2:1, 2:2 equivalency table, no GPA).", "english": "No Ghana-specific scores. Page says check course finder for course English requirements; pre-sessional English offered.", "how_to_apply": "Page links to an Application guide; Ghana-based agents listed.", "fees_link": "https://www.brighton.ac.uk/international/applying-here/fees-and-scholarships/index.aspx", "ghana_page_link": "https://www.brighton.ac.uk/international/study-with-us/your-country-or-territory-info/ghana.aspx", "sources": ["https://www.brighton.ac.uk/international/study-with-us/your-country-or-territory-info/ghana.aspx"]}$q$::jsonb, admission_link = $q$https://www.brighton.ac.uk/international/study-with-us/your-country-or-territory-info/ghana.aspx$q$, admission_checked = '2026-11-13' where id = '1c9af7e8-0fe3-4067-8a71-4fff11458c0a' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Completed Bristol International Foundation Programme (with Kaplan) or another foundation, or first year of a Ghanaian bachelor degree, or IB/A Levels, then course requirements. WASSCE grades not stated. Check course pages.", "pg": "Degree equivalent to UK 2:1 for most Masters. Ghanaian degrees must be accredited by GTEC for the whole period of study. Masters needed for PhD.", "english": "Applicants who completed high school in Ghana are usually exempt, and those with a Ghanaian degree are usually exempt. See Bristol English language requirements page.", "how_to_apply": "UG: UCAS, code BRISL B78. PG: online application on the University postgraduate page. IDP Ghana is an official representative.", "fees_link": "https://www.bristol.ac.uk/international/fees-finance/", "ghana_page_link": "https://bristol.ac.uk/international/countries/ghana.html", "sources": ["https://bristol.ac.uk/international/countries/ghana.html"]}$q$::jsonb, admission_link = $q$https://bristol.ac.uk/international/countries/ghana.html$q$, admission_checked = '2026-11-13' where id = '30a59794-2f18-42d6-a864-1fc218fc68ec' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana page lists West African Senior School Certificate or SSSC with a Grade C profile, or Ordinary National Diploma pass. Foundation route via ONCampus guarantees entry to a range of programmes. Indicative only; varies by course and year.", "english": "WAEC English grade C6 (equates to WASSCE C6), or IELTS 6.0 or equivalent (standard requirement).", "ghana_page_link": "https://www.uclan.ac.uk/international-students/country/ghana", "sources": ["https://www.uclan.ac.uk/international-students/country/ghana"]}$q$::jsonb, admission_link = $q$https://www.uclan.ac.uk/international-students/country/ghana$q$, admission_checked = '2026-11-13' where id = '671b712b-63d7-45f0-8301-4b6057370923' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Foundation Year: WAEC with grades 1-8 in 4 relevant subjects. National Diploma with good grades. HND with 50%/C or above may be considered for 3rd year entry. No direct WASSCE degree entry grade stated.", "pg": "Bachelor degree with a 2:2 or GPA 2.51 or above. Courses needing a 2:1 have higher equivalency. MBA ideally 2 years work experience.", "english": "WAEC/WASSCE C or C6 or above for UG and PG. Level depends on course.", "fees_link": "https://www.chester.ac.uk/international/fees-scholarships-and-finance/fees/", "ghana_page_link": "https://chester.ac.uk/international/countries/ghana/", "sources": ["https://chester.ac.uk/international/countries/ghana/", "https://www.chester.ac.uk/international/how-to-apply/entry-requirements/"]}$q$::jsonb, admission_link = $q$https://chester.ac.uk/international/countries/ghana/$q$, admission_checked = '2026-11-13' where id = '5aa969fc-1862-4666-a720-7de98a1771c5' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Page's West Africa block (not Ghana labelled): SSSC or WASSC plus first year of a bachelor degree, or Ordinary/Higher Diploma with GPA 3.0/5.0 or 2.5/4.0, or recognised International Foundation Programme.", "pg": "West Africa block: Bachelor (Honours) degree with minimum GPA 2.5/5.0 or 55%.", "sources": ["https://chi.ac.uk/?p=4115"]}$q$::jsonb, admission_link = $q$https://chi.ac.uk/?p=4115$q$, admission_checked = '2026-11-13' where id = '85be42b0-0357-4d7a-a226-2f3666bdff91' and country ilike 'United Kingdom';
update schools set admission_info = $q${"how_to_apply": "See How to apply page on the international site.", "fees_link": "https://www.cumbria.ac.uk/study/international-students/fees-and-finance/", "ghana_page_link": "https://www.cumbria.ac.uk/study/international-students/find-my-country/name-107986-en.php", "sources": ["https://cumbria.ac.uk/study/international-students/entry-requirements", "https://www.cumbria.ac.uk/study/international-students/find-my-country/"]}$q$::jsonb, admission_link = $q$https://www.cumbria.ac.uk/study/international-students/find-my-country/name-107986-en.php$q$, admission_checked = '2026-11-13' where id = '2f72d4ab-31a5-4553-8690-ccf1e09ede1e' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "International Foundation Year usually needs five Grade C passes in WASSCE or GCE O Level. Direct year 1 entry: Ordinary National Diploma CGPA 2.5. Final year entry: HND CGPA 2.5. A Levels comparable to UK A Levels. No direct WASSCE degree entry stated.", "pg": "Bachelor degree from a NARIC or government recognised institution.", "english": "UG: WASSCE C6 equals IELTS 6.0, B3 equals 7.0. PG: WASSCE C6 may count as 6.0 or 6.5 only with 4 years of university study in English; IELTS 7+ needs a test. Foundation: UKVI IELTS 4.5, min 4.0 each.", "how_to_apply": "Apply online through the University's online application for UG or PG. Contact international recruitment officer for Ghana questions.", "deadlines": "No general deadlines stated for Ghana.", "fees_link": "https://www.derby.ac.uk/study/fees-finance/international/", "ghana_page_link": "https://derby.ac.uk/life/international-students/africa", "sources": ["https://derby.ac.uk/life/international-students/africa"]}$q$::jsonb, admission_link = $q$https://derby.ac.uk/life/international-students/africa$q$, admission_checked = '2026-11-13' where id = '320c02e9-ef52-430e-885f-d1d10c6214d8' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Page says to use the course entry requirements tool, choose Ghana, then your qualification. International College Dundee offers routes for those below grade requirements. No WASSCE grades on page.", "pg": "Same course tool for taught PG. PhD requirements on separate research page.", "english": "Must meet University English requirements (separate guide page). No scores on Ghana page.", "ghana_page_link": "https://www.dundee.ac.uk/countries/ghana", "sources": ["https://www.dundee.ac.uk/countries/ghana"]}$q$::jsonb, admission_link = $q$https://www.dundee.ac.uk/countries/ghana$q$, admission_checked = '2026-11-13' where id = '7dc2f30c-b488-4bd0-a09a-73febcb0b6b1' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghanaian Senior School Certificate and West African Senior School Certificate are not suitable for direct Year 1 entry. Applicants need another qualification or a foundation programme, such as at the Durham University International Study Centre.", "pg": "Taught PG: a four-year bachelor's degree from a Ghanaian university. No grade stated on this page.", "english": "No Ghana detail; see general English Language Requirements page.", "fees_link": "https://durham.ac.uk/study/international/fees-and-funding/", "ghana_page_link": "https://www.durham.ac.uk/study/international/regional-pages/africa--middle-east-", "sources": ["https://www.durham.ac.uk/study/international/regional-pages/africa--middle-east-", "https://durham.ac.uk/study/international/entry-requirements/international-qualifications/"]}$q$::jsonb, admission_link = $q$https://www.durham.ac.uk/study/international/regional-pages/africa--middle-east-$q$, admission_checked = '2026-11-13' where id = '83cb8ef5-8dcd-4dc1-932a-abfa36aaf51e' and country ilike 'United Kingdom';
update schools set admission_info = $q${"how_to_apply": "Apply via the UEA apply page; admissions@uea.ac.uk for queries.", "ghana_page_link": "https://www.uea.ac.uk/study/international-students/country-map/ghana", "sources": ["https://www.uea.ac.uk/study/international-students/country-map/ghana", "https://www.uea.ac.uk/study/international-students/country-map/west-africa"]}$q$::jsonb, admission_link = $q$https://www.uea.ac.uk/study/international-students/country-map/ghana$q$, admission_checked = '2026-11-13' where id = 'ebb63931-52cf-4694-835c-381d2e1daa07' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana page (2026, January 2027 intake) lists: Ordinary National Diploma (min second class lower), WAEC A levels with 3 grades C or above, year 1 of a relevant degree from a recognised university, BTech from a Polytechnic, or a recognised international foundation course. WASSCE not named.", "pg": "Bachelor's (Honours) degree with minimum second class lower, or a Postgraduate Diploma.", "english": "SSCE (WAEC/NECO) English grade C6 or above, or IELTS, TOEFL iBT, PTE or Oxford test. No scores on page.", "how_to_apply": "Direct application, see How to apply as an international student. Steps include deposit, pre-CAS check, CAS.", "deadlines": "See UEL international admission deadlines page (dates not read).", "fees_link": "https://www.uel.ac.uk/study/fees-funding/international-fees-funding", "ghana_page_link": "https://www.uel.ac.uk/international/guidance-your-region/africa/ghana", "sources": ["https://www.uel.ac.uk/international/guidance-your-region/africa/ghana"]}$q$::jsonb, admission_link = $q$https://www.uel.ac.uk/international/guidance-your-region/africa/ghana$q$, admission_checked = '2026-11-13' where id = 'c38015a2-293b-4a2a-9a98-10da18f519b8' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Edinburgh does not currently accept the WAEC Senior School Certificate for direct entry; applicants usually need a foundation year, e.g. the International Foundation Programme. A Levels, IB and US qualifications are accepted. Page dated 12 November 2024.", "english": "Varies by programme. See English language advice page.", "ghana_page_link": "https://www.ed.ac.uk/studying/international/country/africa/ghana", "sources": ["https://www.ed.ac.uk/studying/international/country/africa/ghana"]}$q$::jsonb, admission_link = $q$https://www.ed.ac.uk/studying/international/country/africa/ghana$q$, admission_checked = '2026-11-13' where id = 'aac45286-070b-4f4b-b5bc-df142e16682d' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana page: bachelor degrees need previous university or college study or a foundation degree in addition to high school qualifications. IB and SAT options listed. WASSCE not mentioned. Foundation via University of Essex International College.", "pg": "Many Masters accept a 2:2 or CGPA 2.75/4 or above; some need more. PhD usually needs a UK 2:2 equivalent and a good Masters plus research proposal.", "how_to_apply": "PG enquiries: pgadmit@essex.ac.uk.", "ghana_page_link": "https://essex.ac.uk/international/country-specific-information/ghana", "sources": ["https://essex.ac.uk/international/country-specific-information/ghana"]}$q$::jsonb, admission_link = $q$https://essex.ac.uk/international/country-specific-information/ghana$q$, admission_checked = '2026-11-13' where id = 'd438a1a9-bb01-48da-9498-a21c94aa64cc' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana page (2027/28 entry): A Levels or IB for direct entry. WASSC holders normally need a foundation programme first, such as the International Study Centre foundation at Streatham Campus.", "pg": "Taught PG: 4-year bachelor's from an NAB accredited university. 2:1 equals GPA 3.0-3.49/4.0 or 3.50-4.49/5.0; 2:2 equals 2.0-2.99/4.0 or 2.50-3.49/5.0. PhD: relevant Masters plus strong research proposal.", "english": "Scores not on Ghana page; see Exeter English language requirements page.", "how_to_apply": "UG: Exeter apply page. Masters: Exeter masters apply page. PhD: pg-research apply page.", "deadlines": "Masters scholarship for January 2027 offer holders: until 26 November 2026.", "fees_link": "https://www.exeter.ac.uk/international-students/funding-scholarships/", "ghana_page_link": "https://www.exeter.ac.uk/international-students/ghana/", "sources": ["https://www.exeter.ac.uk/international-students/ghana/"]}$q$::jsonb, admission_link = $q$https://www.exeter.ac.uk/international-students/ghana/$q$, admission_checked = '2026-11-13' where id = '116cb664-56cc-44ef-b914-84901da71147' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana page gives no WASSCE grades; says check each undergraduate programme page.", "pg": "Check each postgraduate taught programme page. No grades on Ghana page.", "ghana_page_link": "https://www.gla.ac.uk/international/country/ghana", "sources": ["https://www.gla.ac.uk/international/country/ghana"]}$q$::jsonb, admission_link = $q$https://www.gla.ac.uk/international/country/ghana$q$, admission_checked = '2026-11-13' where id = 'f1ba8408-1452-4a4b-a1a0-dbb9022a4a82' and country ilike 'United Kingdom';
update schools set admission_info = $q${"english": "Ghana: English proficiency letter or Medium of Instruction letter from a recognised Ghanaian university accepted, degree within 10 years. WAEC English C6 meets IELTS 5.5, 6.0 and 6.5 levels, C4 for 7.0, valid 10 years. Most UG: IELTS 6.0, no band under 5.5. Most PGT: IELTS 6.0, no band under 5.5.", "ghana_page_link": "https://www.glos.ac.uk/international/country-specific-information/ghana/", "sources": ["https://www.glos.ac.uk/international/english-language-requirements/"]}$q$::jsonb, admission_link = $q$https://www.glos.ac.uk/international/country-specific-information/ghana/$q$, admission_checked = '2026-11-13' where id = '940a1726-859c-4338-886b-7a98779f0faa' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Year 1: WAEC or SSSCE with B2 or A1 may be considered, or WAEC plus a recognised foundation, or OND/ND with credit or distinction profile. International Foundation Year: WAEC with minimum C6 in all subjects incl. Maths and English. Year 2 or 3: HND, Aptech Advanced Diploma or DNIIT, case by case.", "pg": "Successful completion of a four-year first degree.", "english": "WAEC with minimum C6 accepted if completed within the last 5 years; otherwise a recognised test such as IELTS.", "how_to_apply": "UG via UCAS (2027 entry link on page). African applicants are advised to use the Africa Branch Office (AFBO).", "documents": "Qualifications and proof of English; no list given.", "fees_link": "https://greatermanchester.ac.uk/fees-and-funding/", "ghana_page_link": "https://greatermanchester.ac.uk/ghana-contacts/", "sources": ["https://greatermanchester.ac.uk/ghana-contacts/"]}$q$::jsonb, admission_link = $q$https://greatermanchester.ac.uk/ghana-contacts/$q$, admission_checked = '2026-11-13' where id = '08cad281-3c20-4811-a4c0-df538a979164' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Year 1 needs A levels or IB. ND or HND may be considered for year 2 or 3 by grade. Part-completed degrees assessed case by case.", "pg": "Completed 4-year bachelor's degree with minimum 2.2 (Second Class Lower).", "english": "Ghanaian SSCE (WASSCE) English at grade C6 or above can exempt you from IELTS.", "how_to_apply": "UG: via agent or UCAS. PG: direct online application form or through an agent.", "fees_link": "https://www.gre.ac.uk/finance", "ghana_page_link": "https://www.gre.ac.uk/international/countries/ghana", "sources": ["https://www.gre.ac.uk/international/countries/ghana"]}$q$::jsonb, admission_link = $q$https://www.gre.ac.uk/international/countries/ghana$q$, admission_checked = '2026-11-13' where id = 'c31825d7-efe2-440c-a94e-7a92cd6b57de' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Year 1: completion of A levels or IB. Foundation: SSSCE with 5 credit passes (grade C equivalent). Year 2/3: assessed individually. Page does not mention WASSCE.", "pg": "Taught PG: 4-year bachelor's with minimum 2.2. Pre-masters: 4-year bachelor's with third class honours.", "english": "IELTS: foundation 4.5 (no band under 4.0); UG 6.0 (no band under 5.5); pre-masters 5.5; PGT 6.0 or 6.5 by course.", "how_to_apply": "Submit copies of academic transcripts and awards. Contact the Ghana representative for help.", "documents": "Copies of academic transcripts and awards.", "ghana_page_link": "https://herts.ac.uk/international/guidance-for-your-region/africa/ghana", "sources": ["https://herts.ac.uk/international/guidance-for-your-region/africa/ghana"]}$q$::jsonb, admission_link = $q$https://herts.ac.uk/international/guidance-for-your-region/africa/ghana$q$, admission_checked = '2026-11-13' where id = 'ae23a315-1132-4709-a125-80d473499cfc' and country ilike 'United Kingdom';
