update schools set admission_info = $q${"ug": "Ghana page gives no grades; says requirements vary by course.", "how_to_apply": "Hull has step-by-step application guides for UG, PGT and PGR on its international site.", "fees_link": "https://www.hull.ac.uk/study/postgraduate-taught/fees-and-funding", "ghana_page_link": "https://www.hull.ac.uk/study/international-students/your-country/ghana", "sources": ["https://www.hull.ac.uk/study/international-students/your-country/ghana"]}$q$::jsonb, admission_link = $q$https://www.hull.ac.uk/study/international-students/your-country/ghana$q$, admission_checked = '2026-11-13' where id = '912da2b5-27ca-464f-8917-3b1fda7d4c98' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Keele states it is not currently accepting applications from Ghana for 2027 start dates. Grades vary by course; Foundation Year via Keele University International College for those below direct entry. No WASSCE grades listed.", "pg": "Refers to UK 2.2 and 2.1 standards by course; no Ghana grades given.", "english": "UG year 1 and PG: WASSCE/WAEC English grade C6 or above, or IELTS; varies by course.", "how_to_apply": "Contact the Ghana representative (enquiries@keele.ac.uk) or an authorised agent.", "deadlines": "Accommodation guarantee for September starters applying by 30 June.", "fees_link": "https://www.keele.ac.uk/study/internationalstudents/tuitionfeesandscholarships/", "ghana_page_link": "https://keele.ac.uk/study/internationalstudents/yourcountry/africa/ghana", "sources": ["https://keele.ac.uk/study/internationalstudents/yourcountry/africa/ghana"]}$q$::jsonb, admission_link = $q$https://keele.ac.uk/study/internationalstudents/yourcountry/africa/ghana$q$, admission_checked = '2026-11-13' where id = 'ad798243-2d5f-4884-ae45-5d9d2f402005' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Qualifications completed within 4 years of start. Stage 1: HND or Diploma 2nd Class Lower (50%+) or GPA 2.51+. Foundation: HND 3rd class 40%+ or GPA 2.01+. Maths at WASSCE-equivalent C4. WASSCE direct entry not stated.", "pg": "Completed within 8 years. UK 2.2 equals 2nd Class Lower or CGPA 2.00; UK 2.1 equals 2nd Class Upper or CGPA 2.50. PhD: find a supervisor first.", "english": "Standard meets visa minimum, higher for some courses. Foundation and pre-sessional need a UKVI SELT. Scores not given.", "how_to_apply": "See Kent international How to apply page.", "deadlines": "No dates; deposit policy page covers deposit deadlines.", "application_fee": "International fee deposit GBP 5,000 before CAS, deducted from tuition (not an application fee).", "documents": "No full list. SELT for foundation and pre-sessional.", "fees_link": "https://www.kent.ac.uk/finance-student/fees/tuition/index.html", "ghana_page_link": "https://www.kent.ac.uk/international/countries/ghana", "sources": ["https://www.kent.ac.uk/international/countries/ghana"]}$q$::jsonb, admission_link = $q$https://www.kent.ac.uk/international/countries/ghana$q$, admission_checked = '2026-11-13' where id = '70cabf26-596b-46c2-9a8f-7742bbd9776c' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana page (modified Dec 2025): a foundation programme such as Leeds International Foundation Year, or A levels or IB. HNDs considered case by case. WAEC results should be shared via the WAEC website for verification.", "pg": "A 3 to 4 year Bachelor's degree. Page gives 1st, 2.1 and 2.2 equivalents, no GPA.", "english": "UG: WASSCE English C6, or IELTS 6.0 overall. PG: WASSCE English C6, or IELTS 6.5 overall. Exempt if two years of a Ghanaian UG degree (or one year of a Masters for PG) taught in English.", "documents": "WAEC results verification via WAEC website; no other list.", "ghana_page_link": "https://www.leeds.ac.uk/admissions-qualifications/21913/ghana", "sources": ["https://www.leeds.ac.uk/admissions-qualifications/21913/ghana"]}$q$::jsonb, admission_link = $q$https://www.leeds.ac.uk/admissions-qualifications/21913/ghana$q$, admission_checked = '2026-11-13' where id = '4bfd381e-8ae5-4747-bc35-b4934098e585' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "A level or IB holders enter year 1. First year of a relevant Ghanaian degree may be considered for year 1 entry. WAEC results accepted; grades not on Ghana page.", "pg": "Ghanaian Bachelor's with at least second class honours; some courses need second class upper. PhD: at least a 2:1 equivalent from a recognised Ghanaian university; some need a Masters.", "english": "PG applicants with one or more years at a recognised Ghanaian university need no extra English evidence. Others may use WAEC results; grades on English requirements page (not read).", "ghana_page_link": "https://le.ac.uk/study/international-students/countries/africa/ghana", "sources": ["https://le.ac.uk/study/international-students/countries/africa/ghana"]}$q$::jsonb, admission_link = $q$https://le.ac.uk/study/international-students/countries/africa/ghana$q$, admission_checked = '2026-11-13' where id = '14a32f01-da3b-4ca2-adc0-aa728d19ff2e' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Year 1 needs WASSCE plus an international foundation year, a recognised International Foundation programme, IB Diploma 27 to 34 points, or three A Levels. Level 2 or 3 entry may be possible (intadmissions@lincoln.ac.uk).", "pg": "Bachelor's or equivalent; grade varies by programme from first to lower second. 2:1 = 2.9/4.0 or 3.5/5.0 GPA; 2:2 = 2.5/4.0 or 2.8/5.0 GPA.", "english": "Most programmes IELTS 6.0, 6.5 or 7.0. WASSCE English C6 accepted for IELTS 6.0 courses (scratch card PIN needed), usually under 5 years old.", "how_to_apply": "Start at the Applying to Lincoln page; agents may be used.", "fees_link": "https://lincoln.ac.uk/studywithus/feesandfunding/", "ghana_page_link": "https://lincoln.ac.uk/studywithus/internationalstudents/entryrequirementsandyourcountry/ghana", "sources": ["https://lincoln.ac.uk/studywithus/internationalstudents/entryrequirementsandyourcountry/ghana"]}$q$::jsonb, admission_link = $q$https://lincoln.ac.uk/studywithus/internationalstudents/entryrequirementsandyourcountry/ghana$q$, admission_checked = '2026-11-13' where id = '309bee15-3f31-471a-a41b-6e51c252a7d5' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "SSCE/WASSCE plus either a Foundation Certificate at University of Liverpool International College, or first year of a recognised Ghanaian degree. IB Diploma min 28 points or A levels also accepted.", "pg": "Bachelor's with a 2:2, GPA 2.5/4.0 or 55%. Some courses higher. Pre-Master's available. PhD: Masters at higher second division.", "english": "UG and Masters: WAEC with credit (grades 4 to 6) or above. Pre-sessional English available.", "how_to_apply": "UG via UCAS. Masters and research via the Apply Yourself portal. Approved agents may be used.", "fees_link": "https://www.liverpool.ac.uk/international/scholarships-and-fees/tuition-fees/", "ghana_page_link": "https://liverpool.ac.uk/international/countries/ghana.php", "sources": ["https://liverpool.ac.uk/international/countries/ghana.php"]}$q$::jsonb, admission_link = $q$https://liverpool.ac.uk/international/countries/ghana.php$q$, admission_checked = '2026-11-13' where id = '05eb69e7-21dd-43c0-a30d-20cf349c46a6' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Science and Engineering integrated foundation: B3 in five relevant subjects incl. Maths and Physics, rest C4+, WAEC English C6. Humanities, Social Sciences, Law, Nursing, Psychology: five SSCE passes at B3+ for INTO foundation. Degree entry: SSSCE/WASSCE plus recognised foundation, three A levels, IB, or ND/HND at Upper Credit.", "pg": "Taught Masters: bachelor's with at least 2:1 or GPA 3.5/5.0; some accept a good 2:2. Research: Masters from a good university; contact supervisor.", "english": "IELTS and TOEFL iBT accepted. WAEC English within 7 years may be accepted at B3 or B2 by course. PG waiver possible if Ghanaian degree taught fully in English.", "how_to_apply": "UG must apply through UCAS. PG steps not given.", "ghana_page_link": "https://www.manchester.ac.uk/study/international/country-specific-information/ghana/entry-requirements/", "sources": ["https://www.manchester.ac.uk/study/international/country-specific-information/ghana/entry-requirements/"]}$q$::jsonb, admission_link = $q$https://www.manchester.ac.uk/study/international/country-specific-information/ghana/entry-requirements/$q$, admission_checked = '2026-11-13' where id = 'b9027acc-56c3-47da-9320-2b2a37a60169' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Page gives no WASSCE grades; check undergraduate course pages.", "pg": "No Ghana-specific requirement; see postgraduate course pages.", "english": "Non-native speakers generally need IELTS 6.5 or equivalent; some courses differ.", "how_to_apply": "UG via UCAS. PG via the university online portal.", "deadlines": "PG Excellence Scholarship (2027 entry) closes 08 June 2027.", "fees_link": "https://www.ncl.ac.uk/tuition-fees/how-to-pay/", "ghana_page_link": "https://www.ncl.ac.uk/international/country/ghana/", "sources": ["https://www.ncl.ac.uk/international/country/ghana/"]}$q$::jsonb, admission_link = $q$https://www.ncl.ac.uk/international/country/ghana/$q$, admission_checked = '2026-11-13' where id = '909aeeb6-711a-4126-9a2d-16b9d55fd559' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana page (2026): year 1 of a degree from a recognised institution, OND, IB Certificate, UK awarding body Foundation, A Levels, or WASSCE plus a recognised Foundation programme. A 4-year option with Integrated Foundation Year may be offered.", "pg": "Taught Masters: bachelor's from a recognised university, or a recognised pre-Master's.", "english": "Bachelor's: IELTS 6.0, no score under 5.5. Masters: IELTS 6.5, no score under 5.5 (or equivalent). Some courses differ. Pre-sessional English available.", "how_to_apply": "Contact approved Ghana representatives or the International Officer; no steps given.", "ghana_page_link": "https://www.northampton.ac.uk/international/your-country/sub-saharan-africa/", "sources": ["https://www.northampton.ac.uk/international/your-country/sub-saharan-africa/"]}$q$::jsonb, admission_link = $q$https://www.northampton.ac.uk/international/your-country/sub-saharan-africa/$q$, admission_checked = '2026-11-13' where id = '52c33587-b13a-4e4c-8216-2419db331ddb' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "International Foundation Programme: WAEC (WASSCE) or NECO with A to D grades in 5 subjects. Polytechnic National Diploma for 1st year entry; University Diploma for Level 5; Polytechnic HND for Level 6 (grades not stated). Course specific criteria vary.", "pg": "Bachelor degree needed. 2:2 courses: second class lower (50%, C or 2.0). 2:1 courses: second class upper (60%, B or 3.0). Graduate Certificate: 1.5/4.0 CGPA or 40%.", "english": "Most degree level courses: WAEC typically C6. NECO (from September 2022 intake) typically B3. May not be accepted for some health or professional courses. Pre-sessional pages hold other requirements.", "documents": "Upload WAEC or NECO certificate where possible, and a copy of the scratch card where applicable.", "ghana_page_link": "https://www.northumbria.ac.uk/international/northumbria-and-your-country/africa/ghana/", "sources": ["https://www.northumbria.ac.uk/international/northumbria-and-your-country/africa/ghana/"]}$q$::jsonb, admission_link = $q$https://www.northumbria.ac.uk/international/northumbria-and-your-country/africa/ghana/$q$, admission_checked = '2026-11-13' where id = 'f02b428f-c2d4-41c1-a35d-c171b3d32155' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "SSC/WAEC year 12 exams: an appropriate foundation programme is required (Nottingham International College with Kaplan). HND with average 3.0 to 5.0 typically accepted. One year of good grades at a Ghanaian university may be considered for direct entry. Page updated Feb 2025.", "pg": "A good standard degree from a recognised university, usually in a relevant subject. Ghanaian second upper or second lower generally meets 2:1 and 2:2 requirements. Full transcript is reviewed.", "english": "Degrees from recognised Ghanaian universities can be accepted for postgraduate and research courses. No undergraduate scores listed on this page.", "how_to_apply": "Foundation applications go through Kaplan and the International College. Other how to apply details are on separate pages.", "documents": "Full transcript reviewed for masters. PhD: research proposal.", "ghana_page_link": "https://www.nottingham.ac.uk/studywithus/international-applicants/country-info/countryinformation/ghana.aspx", "sources": ["https://www.nottingham.ac.uk/studywithus/international-applicants/country-info/countryinformation/ghana.aspx"]}$q$::jsonb, admission_link = $q$https://www.nottingham.ac.uk/studywithus/international-applicants/country-info/countryinformation/ghana.aspx$q$, admission_checked = '2026-11-13' where id = '4dca123b-9db3-472f-b2dd-30458b913969' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "First year entry: WASSCE with C6 or above in English and Maths, plus West African GCE A Level with good grades (AAA=144 down to CCC=96 UCAS points listed). HND may be considered for advanced entry. Foundation options via the University or UPIC.", "pg": "Ghanaian bachelor degree from a recognised institution: first class, second class upper or second class lower.", "english": "A recognised English qualification such as WAEC, NECO or IELTS, or a University pre-sessional course. No minimum scores stated.", "how_to_apply": "Ghana applications only through University contracted agents (seven listed on the page). Route at plymouth.ac.uk/international/apply.", "deadlines": "Page states the University is not currently issuing CAS to Ghanaian applicants for January 2027 and September 2027 intakes. No application deadlines stated.", "documents": "Not listed beyond academic qualifications and English evidence.", "ghana_page_link": "https://www.plymouth.ac.uk/international/study/international-students-country-guides/ghana", "sources": ["https://www.plymouth.ac.uk/international/study/international-students-country-guides/ghana"]}$q$::jsonb, admission_link = $q$https://www.plymouth.ac.uk/international/study/international-students-country-guides/ghana$q$, admission_checked = '2026-11-13' where id = 'bfabc276-11ff-4d07-b003-40ab7fbe27f2' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Foundation year usually needed: minimum grades 1 to 6 or A to D in 5 SSCE/WASSCE subjects incl. maths and English (International College Portsmouth). Direct entry via A levels or IB 24 to 31 points. OND or HND may give entry or advanced entry. Page is for January 2027 intake.", "pg": "Bachelor degree from recognised institution. Typical minimum UK 2:1 equivalent is 65% or GPA 2.75/4.0; 2:2 is 55% or GPA 2.50/4.0. Some courses need higher. Pre-masters at ICP available. PhD: good Master's and research proposal.", "english": "WASSCE grade C6 or above in English accepted, with scratch card to verify. IELTS, IGCSE and others accepted. Pre-sessional available. Course pages list specifics.", "how_to_apply": "Must apply through an approved Portsmouth agent in Ghana. Direct applications not considered.", "deadlines": "January 2027 intake: deposit due 30 Nov 2026 (Portsmouth campus) or 23 Nov 2026 (London campus). Reduced deposit of 6000 GBP for Ghanaian students.", "documents": "WASSCE scratch card to verify results; CAS needed for visa after deposit.", "ghana_page_link": "https://www.port.ac.uk/study/international-students/your-country/ghana", "sources": ["https://www.port.ac.uk/study/international-students/your-country/ghana", "https://www.port.ac.uk/study/international-students/how-to-apply/application-deadlines"]}$q$::jsonb, admission_link = $q$https://www.port.ac.uk/study/international-students/your-country/ghana$q$, admission_checked = '2026-11-13' where id = 'd162b3af-a079-4915-979e-af94a39e5433' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "International Foundation Programme: Senior Secondary School Certificate Examination with five high passes at Grade C or above. Degree entry via the IFP or other accepted qualifications on the undergraduate entry page; no Ghana grades given.", "pg": "Master's and MPhil: Bachelor's (Honours) degree with 2.2 to 2.1 or GPA from 2.50 to 3.0/4. PhD requirements vary by programme.", "ghana_page_link": "https://www.reading.ac.uk/ready-to-study/international-and-eu/country-specific-information/country-specific-ghana", "sources": ["https://www.reading.ac.uk/ready-to-study/international-and-eu/country-specific-information/country-specific-ghana"]}$q$::jsonb, admission_link = $q$https://www.reading.ac.uk/ready-to-study/international-and-eu/country-specific-information/country-specific-ghana$q$, admission_checked = '2026-11-13' where id = '903e25ca-e816-4b7d-95e9-a2ed711f1a94' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Considered: university or polytechnic diploma, university certificate, technician part 3 certificate, a recognised foundation, or West African higher school certificate/GCE A level. WASSCE grades not stated.", "pg": "Bachelor's degree awarded at least second class (lower division), or a master's degree.", "ghana_page_link": "https://www.salford.ac.uk/international/your-country-or-region/ghana", "sources": ["https://www.salford.ac.uk/international/your-country-or-region/ghana"]}$q$::jsonb, admission_link = $q$https://www.salford.ac.uk/international/your-country-or-region/ghana$q$, admission_checked = '2026-11-13' where id = 'e31eb188-42d1-47b1-baa3-1a539cd7f7d4' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Direct entry for applicants with at least three A Levels or IB Diploma; scores in online prospectus. No WASSCE grades listed. Foundation route: International Foundation Years at University of Sheffield International College.", "pg": "Usually a 4 to 6 year bachelor degree, GTEC accredited. Most courses UK 2:1 (60%, GPA 3.0), some 2:2 (50%, GPA 2.0); first class 70%, GPA 3.6/4.0. MBA needs 3 years work experience. PhD: usually bachelor plus master. Pre-Masters available.", "english": "Internationally recognised English test such as IELTS (scores in prospectus). WASSCE English grade C or above can be accepted in place of IELTS.", "ghana_page_link": "https://www.sheffield.ac.uk/international/countries/africa/west-africa/ghana/entry", "sources": ["https://www.sheffield.ac.uk/international/countries/africa/west-africa/ghana/entry"]}$q$::jsonb, admission_link = $q$https://www.sheffield.ac.uk/international/countries/africa/west-africa/ghana/entry$q$, admission_checked = '2026-11-13' where id = '89e22c5f-e246-4816-87e8-d61fdb064af4' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "5 or more WAEC/NECO subjects at B3 or above incl. Maths and one Science may be considered. National Diploma considered; HND or polytechnic diploma for advanced entry; A Levels by UCAS tariff. Foundation Years for those below Year 1 level (IELTS 6.0). Page is for 2026/27.", "pg": "Undergraduate degree at second class or higher for direct entry. Master's can be considered for PhD with a suitable research proposal.", "english": "Senior School Certificate grade C or Credit in English, or IELTS 6.0 with 5.5 in each band (UG and PG). Some courses need higher.", "how_to_apply": "No direct applications from Ghana. Apply through a registered agent or the in-country representative named on the page.", "deadlines": "Intakes: September 2026 and February 2027. No deadlines stated.", "documents": "Not listed beyond academic and English qualifications.", "ghana_page_link": "https://www.southwales.ac.uk/international/your-country/ghana/", "sources": ["https://www.southwales.ac.uk/international/your-country/ghana/"]}$q$::jsonb, admission_link = $q$https://www.southwales.ac.uk/international/your-country/ghana/$q$, admission_checked = '2026-11-13' where id = '26e1f3b5-b007-4ef4-8b63-381c2fb3a040' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Foundation year (engineering, maths, physics): WASSCE average B or B3 in at least 5 subjects, minimum B2 in maths and physics. OnCampus foundation: WASSCE average C6 in at least 5 subjects. Degree entry: A level equivalent, IB 28 to 38, recognised foundation, or first year of a Ghanaian university honours degree.", "pg": "Bachelor degree from a recognised Ghanaian university. UK 1st equivalent 70% or 3.75/4; 2:1 equivalent 60% or 3.25/4. PhD: 2:1 honours, master's with merit, research proposal. Pre-masters needs IELTS 5.0 equivalent.", "english": "Degree entry scores not on this page, which links to a separate English requirements page. Pre-masters: IELTS 5.0 or equivalent, none below 5.0.", "documents": "Qualifications, student visa. Full checklist not stated.", "ghana_page_link": "https://www.southampton.ac.uk/uni-life/international/your-country/africa/ghana.page", "sources": ["https://www.southampton.ac.uk/uni-life/international/your-country/africa/ghana.page"]}$q$::jsonb, admission_link = $q$https://www.southampton.ac.uk/uni-life/international/your-country/africa/ghana.page$q$, admission_checked = '2026-11-13' where id = '4b1603eb-750f-41f4-b89b-d26f9cb406e4' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "International Year Zero foundation (Business, Social Sciences and Humanities), September entry: WASSCE minimum B3 in 5 subjects, a guide only. Direct degree requirements not checked.", "english": "No scores on this page. Offers consider English language evidence with academic results, personal statement and school reference.", "how_to_apply": "Apply through the Foundation students apply page. Email ifp@st-andrews.ac.uk if qualification not listed.", "sources": ["https://www.st-andrews.ac.uk/study/undergraduate/foundation/who-can-apply/academic-requirements-year-zero/"]}$q$::jsonb, admission_link = $q$https://www.st-andrews.ac.uk/study/undergraduate/foundation/who-can-apply/academic-requirements-year-zero/$q$, admission_checked = '2026-11-13' where id = 'bf7f3aa8-1973-4e6b-937a-e58e675b94a5' and country ilike 'United Kingdom';
update schools set admission_info = $q${"how_to_apply": "Undergraduate international students apply through UCAS. Postgraduate applicants can apply directly to the university. Student visa needed for courses over 6 months.", "sources": ["https://www.marjon.ac.uk/courses/international/"]}$q$::jsonb, admission_link = $q$https://www.marjon.ac.uk/courses/international/$q$, admission_checked = '2026-11-13' where id = 'cdbae795-0b76-4732-94a2-8a39b4700cf6' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Bachelor's: GCE A Levels BBC, or ordinary National Diploma GPA 3/5, or IB 28, or relevant International Foundation Year. Integrated masters: BBB, OND GPA 3.5/5 or IB 30. WASSCE not mentioned.", "pg": "Taught: 2:1 courses need minimum 3.25 (Second Class Upper); 2:2 courses need minimum 2.5 (Second Class Lower), in a relevant bachelor degree.", "english": "WAEC or NECO (post 1998) English Language at grade A1 to C6, valid 10 years. Postgraduate: degree taught in English (valid 8 years) or medium of instruction letter may be accepted.", "how_to_apply": "Through approved agents listed on the page; links to Your application journey pages.", "deadlines": "Page refers to January 2026 and September 2026 entry without dates. Admissions may close early.", "documents": "Requested documents and evidence by deadlines. Proof of funds before CAS. Deposit 4000 GBP (full time on campus) before CAS.", "fees_link": "https://www.staffs.ac.uk/international/your-country/ghana", "ghana_page_link": "https://www.staffs.ac.uk/international/your-country/ghana", "sources": ["https://www.staffs.ac.uk/international/your-country/ghana"]}$q$::jsonb, admission_link = $q$https://www.staffs.ac.uk/international/your-country/ghana$q$, admission_checked = '2026-11-13' where id = 'f2284fd4-027c-4164-b37e-d2235072aefe' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Minimum 5 grades at B or above with none below C in WAEC/WASSCE, and B in any essential subject. One year of relevant university study also considered. Pathway programmes via the International Study Centre.", "pg": "Minimum 2.2 degree from a recognised university, equal to CGPA 2.5/4, C+ or 65%. Affiliated institutions may need a higher standard.", "english": "Evidence required; scores not on this page, see separate English language requirements and waiver pages.", "ghana_page_link": "https://www.stir.ac.uk/international/international-students/country-specific-information/africa/ghana/", "sources": ["https://www.stir.ac.uk/international/international-students/country-specific-information/africa/ghana/"]}$q$::jsonb, admission_link = $q$https://www.stir.ac.uk/international/international-students/country-specific-information/africa/ghana/$q$, admission_checked = '2026-11-13' where id = '02b6ec3a-f95a-404f-bc20-8d9a4c93c97c' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSCE is not normally enough for direct entry; a foundation programme is usually needed. IB, A-Levels or American High School Diploma may be considered for direct entry.", "pg": "Honours degree from a prestigious Ghanaian institution, at least second class.", "documents": "Online qualification verification through Qualification Check.", "sources": ["https://www.strath.ac.uk/studywithus/internationalstudents/entryrequirements/"]}$q$::jsonb, admission_link = $q$https://www.strath.ac.uk/studywithus/internationalstudents/entryrequirements/$q$, admission_checked = '2026-11-13' where id = 'c1af869a-6bf8-4d05-94dc-96855cd531e8' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Page does not mention WASSCE. Options: International Foundation from a recognised institution, IB 28 points, or A-levels (see course page).", "pg": "4-year Bachelor's degree with a 2:2 from a central university in Ghana.", "english": "No scores on this page. Accepted tests listed: IELTS (Academic/UKVI), Cambridge English, Pearson Academic, TOEFL iBT. See English Language page for course requirements.", "deadlines": "Not stated. Scholarships mentioned for 2026/27 entry.", "ghana_page_link": "https://www.uos.ac.uk/international/countries/ghana/", "sources": ["https://www.uos.ac.uk/international/countries/ghana/"]}$q$::jsonb, admission_link = $q$https://www.uos.ac.uk/international/countries/ghana/$q$, admission_checked = '2026-11-13' where id = 'dedea4a1-14e5-4b64-92e2-d0a5ecf73dcf' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana specific requirements not stated on the page. If direct entry requirements are not met, the International Foundation Programme is an option.", "how_to_apply": "Apply directly on the University website, via UCAS (undergraduate only), overseas offices, in-country representatives or Study Centres. Some courses need an interview, audition or portfolio.", "documents": "Offer conditions include deposit and tuition fees. Other documents not listed.", "sources": ["https://www.sunderland.ac.uk/how-to-apply/international-students"]}$q$::jsonb, admission_link = $q$https://www.sunderland.ac.uk/how-to-apply/international-students$q$, admission_checked = '2026-11-13' where id = '890c87b2-1836-466d-9c21-682267722e24' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "The University does not accept the Ghanaian Senior Secondary School Certificate for direct entry. Option: International Foundation Year at the Surrey International Study Centre (three routes).", "pg": "2:1 courses: GPA 3.25 or a 2:1 honours degree. 2:2 courses: GPA 2.5 or a 2:2 honours degree. Pre-Masters available in Management, Finance, Hospitality and Tourism.", "english": "West African Senior School Certificate or Senior School Certificate at grade C6; evidence of grade needed. Some courses need higher. Pre-sessional courses available.", "how_to_apply": "Masters applications must use the appointed in-country agent (no extra cost).", "documents": "Evidence of English certificate grade.", "ghana_page_link": "https://www.surrey.ac.uk/ghana/entry-requirements", "sources": ["https://www.surrey.ac.uk/ghana/entry-requirements"]}$q$::jsonb, admission_link = $q$https://www.surrey.ac.uk/ghana/entry-requirements$q$, admission_checked = '2026-11-13' where id = '46099416-2b93-4080-83e2-92a62c95824c' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Foundation year available for WASSCE holders (criteria with Sussex International Study Centre). Year 1: one year at a recognised Ghanaian university or a foundation year, plus WASSCE with good grades. HND: 55% or 2:2 for Year 1; Year 2 needs two years at a recognised university.", "pg": "Masters: degree with overall mark typically 50% to 65% depending on course. PhD: second class upper from a public university in a relevant subject, or extensive related work experience.", "english": "WASSCE C6 meets the requirement. Typical IELTS: UG and Masters 6.0 overall with 5.5 each component; PhD 6.5 with 6.0 each.", "how_to_apply": "Undergraduate through UCAS; Masters and PhD through their application portals.", "deadlines": "Not stated. 2026-27 scholarships mentioned.", "ghana_page_link": "https://www.sussex.ac.uk/study/international-students/information-by-country/ghana", "sources": ["https://www.sussex.ac.uk/study/international-students/information-by-country/ghana"]}$q$::jsonb, admission_link = $q$https://www.sussex.ac.uk/study/international-students/information-by-country/ghana$q$, admission_checked = '2026-11-13' where id = '7378d03b-2904-41f3-ac6d-d52c5be57021' and country ilike 'United Kingdom';
update schools set admission_info = $q${"english": "If English is not your first language, prove your level, for example IELTS. Accepted qualifications on UAL English requirements page. Pre-sessional English offered.", "how_to_apply": "Through a UAL representative, UCAS for undergraduate, or directly to UAL for pre-degree and postgraduate courses.", "documents": "Personal statement, academic transcripts in English, English certificate, passport and any UK visa, immigration history form, portfolio for practice courses.", "sources": ["https://www.arts.ac.uk/study-at-ual/international/application-advice"]}$q$::jsonb, admission_link = $q$https://www.arts.ac.uk/study-at-ual/international/application-advice$q$, admission_checked = '2026-11-13' where id = 'de08453b-50a7-4038-a357-c890ad821fb2' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "West African Senior School Certificate: typically WAEC in at least five subjects at an average of B/C, plus the first year of a relevant university degree (first year average B/55% or C/50%, essential subjects B/55%). Varies by course.", "english": "English at C6 or higher in WAEC accepted (valid 5 years).", "sources": ["https://www.uhi.ac.uk/en/studying-at-uhi/international/eligibility/qualification-requirements/"]}$q$::jsonb, admission_link = $q$https://www.uhi.ac.uk/en/studying-at-uhi/international/eligibility/qualification-requirements/$q$, admission_checked = '2026-11-13' where id = '1d595636-bc1a-48ef-bdf8-3d1c9c46a234' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Good WASCCE plus a UK international or bridging foundation course can give direct entry; also A levels, IB, OND upper credit, HND, or first year of a Ghanaian bachelor degree plus English. Foundation or International Year One at International College otherwise.", "pg": "Bachelor's degree with overall GPA of 2.5/4 or 2.7/5 considered.", "english": "Secure English tests, usually IELTS; scores vary by subject and are not on this page. Pre-sessional available.", "ghana_page_link": "https://www.uwe.ac.uk/courses/international-study/country-or-region/ghana", "sources": ["https://www.uwe.ac.uk/courses/international-study/country-or-region/ghana"]}$q$::jsonb, admission_link = $q$https://www.uwe.ac.uk/courses/international-study/country-or-region/ghana$q$, admission_checked = '2026-11-13' where id = '73a2eece-af4a-4b2b-bd36-b6cc4bb7388c' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "No WASSCE grades on the Ghana page; it links to the separate undergraduate entry requirements page.", "english": "All non-native speakers must meet the University criteria; no scores on this page.", "how_to_apply": "Online application system at apply.uws.ac.uk for undergraduate, masters and research.", "deadlines": "Applications open in August each year and run until course start date. No closing dates stated.", "ghana_page_link": "https://www.uws.ac.uk/international/country-information/ghana", "sources": ["https://www.uws.ac.uk/international/country-information/ghana"]}$q$::jsonb, admission_link = $q$https://www.uws.ac.uk/international/country-information/ghana$q$, admission_checked = '2026-11-13' where id = 'a027ce5a-c15c-4860-be00-bf1519498d98' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "International Foundation Year: West African Senior School Certificate with C6 or above in 5 subjects incl. Maths, age 18 by June. Undergraduate: HND with GPA 2.5 or above (or 2:2), or 2 year public university Diploma with 2:2 or GPA 2.5. Varies by programme.", "pg": "Equivalent of a UK first degree, normally relevant. 2:1 normally 60% or GPA 3.25/4; 2:2 normally 50% or GPA 2.5/4.", "english": "Normally IELTS Academic 6.0 with no band below 5.5, or WAEC English C6. Some courses need more.", "how_to_apply": "Use the Apply for Undergraduate or Postgraduate links on the page.", "documents": "WAEC: copy of scratch card. NECO: official documents showing exam and token numbers.", "ghana_page_link": "https://www.ulster.ac.uk/global/apply/country/ghana", "sources": ["https://www.ulster.ac.uk/global/apply/country/ghana"]}$q$::jsonb, admission_link = $q$https://www.ulster.ac.uk/global/apply/country/ghana$q$, admission_checked = '2026-11-13' where id = '84d64601-96fa-452e-825e-f295d2240b4e' and country ilike 'United Kingdom';
update schools set admission_info = $q${"how_to_apply": "Two routes: through an approved agent, or directly as an international student. Contact iru@uwtsd.ac.uk.", "sources": ["https://www.uwtsd.ac.uk/study/how-apply/international-applications"]}$q$::jsonb, admission_link = $q$https://www.uwtsd.ac.uk/study/how-apply/international-applications$q$, admission_checked = '2026-11-13' where id = 'f8c35a8a-f1a8-494f-9e4a-951fbf4623c7' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Ghana GCE A Levels considered (2027 entry page): A*A*A, A*AA and AAA need AAA; AAB needs AAB; ABB needs ABB. IB considered. Diploma or HND may be considered for first year case by case. International Foundation also welcomed (requirement not listed).", "how_to_apply": "Questions to africa@warwick.ac.uk.", "ghana_page_link": "https://warwick.ac.uk/study/undergraduate/courses/ug-international-qualifications/", "sources": ["https://warwick.ac.uk/study/undergraduate/courses/ug-international-qualifications/"]}$q$::jsonb, admission_link = $q$https://warwick.ac.uk/study/undergraduate/courses/ug-international-qualifications/$q$, admission_checked = '2026-11-13' where id = 'e5bf3c77-8364-4f5f-ab16-4c8b6bff5b96' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Integrated Foundation Year: SSSC C6 in six subjects incl. maths. Direct: ND or HND merit GPA 2.6, A Levels min 112 UCAS points, IB min 25, or recognised foundation course.", "pg": "Taught: Bachelor's with Honours, second class lower division or UK 2.2 equivalent. PhD: UK 2:1 plus Master's with merit or distinction, research proposal.", "english": "WAEC English A1 to C6 (A1 to C4 for courses needing higher IELTS) or NECO C5. Scratch card needed to verify. Pre-sessional available.", "how_to_apply": "Search the course, click Apply now on the course page.", "documents": "Scratch card to verify scores. PhD: research proposal.", "ghana_page_link": "https://www.uwl.ac.uk/international/your-country/international-non-eueea-entry-requirements/ghana", "sources": ["https://www.uwl.ac.uk/international/your-country/international-non-eueea-entry-requirements/ghana"]}$q$::jsonb, admission_link = $q$https://www.uwl.ac.uk/international/your-country/international-non-eueea-entry-requirements/ghana$q$, admission_checked = '2026-11-13' where id = 'b8398d6d-a234-46e9-b275-1d447d3a7d8f' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Year 1: GCE A Level, OND/ND upper credit or distinction, HND with credit, or UK recognised International Foundation (normally 60 to 65%). Year 2: University Diploma CGPA 3.0+. Kaplan International College London Foundation offered. WASSCE not mentioned. Page for 2026/27.", "pg": "Bachelor degree from a recognised Ghanaian institution, CGPA 50% or 2.0/4.0 minimum. UK 2:1 courses: 60% or 3.0/4.0. First class: 70% or 3.6/4.0. Kaplan Pre-Master's offered.", "english": "UG: WAEC with minimum C6 accepted, under 8 years old and verified on the WAEC portal. PG: Ghanaian degree under 8 years old may be accepted. IELTS minimums on course pages.", "documents": "Qualification verification may be required via the Qualifications Checker Portal (free).", "ghana_page_link": "https://www.westminster.ac.uk/international/your-country/ghana", "sources": ["https://www.westminster.ac.uk/international/your-country/ghana"]}$q$::jsonb, admission_link = $q$https://www.westminster.ac.uk/international/your-country/ghana$q$, admission_checked = '2026-11-13' where id = '7e6073de-bc9b-4cce-b07e-449822283df2' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "Foundation: West African Examination Certificate, at least five subjects with average C6 or above, or a one year UK foundation. Post School Diploma or HND may be accepted for some courses. Year 1 of a 4-year Ghanaian bachelor degree. A Levels or IB per course page.", "pg": "At least a 2.2 honours degree from a central university in Ghana.", "english": "Refers to the separate English Language Requirements page; no Ghana scores.", "ghana_page_link": "https://www.winchester.ac.uk/international/International-Entry-Requirements/", "sources": ["https://www.winchester.ac.uk/international/International-Entry-Requirements/"]}$q$::jsonb, admission_link = $q$https://www.winchester.ac.uk/international/International-Entry-Requirements/$q$, admission_checked = '2026-11-13' where id = 'e5852981-8d2d-4dc6-8d26-26a843ad3ed1' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSC/SSCE/WAHSC Grade B/C profile, or WASSC/SSCE/WAHSC plus a recognised foundation programme, or first year of a recognised university degree.", "pg": "Typically Bachelor degree at 2:2 or equivalent. Lower GPA with a Postgraduate Diploma (Ghanaian Pre-Masters), or HND with Postgraduate Diploma, may be considered.", "english": "Foundation: IELTS 5.5 (5.5 each). UG and PG: WAEC/WASSCE English C6, or IELTS 6.0 with 5.5 in each element.", "how_to_apply": "Page links to Apply Direct and lists official agents in Ghana.", "ghana_page_link": "https://www.wlv.ac.uk/international/your-country/ghana/", "sources": ["https://www.wlv.ac.uk/international/your-country/ghana/"]}$q$::jsonb, admission_link = $q$https://www.wlv.ac.uk/international/your-country/ghana/$q$, admission_checked = '2026-11-13' where id = 'e4397bda-a1a0-4c7a-8716-138fecd42494' and country ilike 'United Kingdom';
update schools set admission_info = $q${"english": "Applicants must submit an English test result, for example IELTS, Cambridge Advanced or Pearson. No scores on this page.", "how_to_apply": "Full time undergraduate: UCAS (strongly advised) or Common Application. Taught postgraduate: apply directly. PGCE via the government Find postgraduate teacher training site. Local representatives can help.", "deadlines": "No dates given; applications processed as soon as possible.", "documents": "Academic transcripts, degree or diploma certificates, up to two academic references, English test score, personal statement, passport or ID copy.", "sources": ["https://www.worc.ac.uk/study/find-a-course/how-to-apply/international-applications.aspx"]}$q$::jsonb, admission_link = $q$https://www.worc.ac.uk/study/find-a-course/how-to-apply/international-applications.aspx$q$, admission_checked = '2026-11-13' where id = 'e1ad4597-7939-492b-aed9-2bd9d11f4cdb' and country ilike 'United Kingdom';
update schools set admission_info = $q${"ug": "WASSCE alone is not enough: take an additional course first, such as A Levels, IB or a recognised foundation. Foundation or International Year One via the International Pathway College. A Level and IB offers on course pages.", "pg": "Taught: Bachelor's degree at least equal to UK 2:2; upper second comparable to 2:1. Research: bachelor plus relevant masters or research experience. Pre-Masters via International Pathway College.", "english": "UG: WASSCE English grade C6 within last seven years. PG: Ghanaian degree within seven years with medium of instruction letter, or WASSCE/iGCSE English grade 5, may exempt. IELTS and TOEFL iBT accepted; scores on course pages.", "how_to_apply": "UG through UCAS. PG apply online; applications open late September each year.", "ghana_page_link": "https://www.york.ac.uk/study/international/your-country/ghana/", "sources": ["https://www.york.ac.uk/study/international/your-country/ghana/"]}$q$::jsonb, admission_link = $q$https://www.york.ac.uk/study/international/your-country/ghana/$q$, admission_checked = '2026-11-13' where id = '94818231-694c-4573-9223-01f1535f21c2' and country ilike 'United Kingdom';
update schools set admission_info = $q${"how_to_apply": "International students can apply directly for undergraduate and postgraduate courses (page also mentions UCAS and country office routes).", "sources": ["https://www.yorksj.ac.uk/international/how-to-apply/apply-direct/", "https://www.yorksj.ac.uk/international/how-to-apply/your-country/ghana/"]}$q$::jsonb, admission_link = $q$https://www.yorksj.ac.uk/international/how-to-apply/apply-direct/$q$, admission_checked = '2026-11-13' where id = '4d7be9d4-3e18-40df-99bc-8c6b5bc2e04c' and country ilike 'United Kingdom';
